/* Feste Übersetzung der Lerninhalte (fa), maschinell erstellt, nicht von Muttersprachlern geprüft. Code bleibt unverändert. */
(function(r){"use strict";const f=r.SDAkademieFest=r.SDAkademieFest||{};(f["fa"]=f["fa"]||{})["javascript"]={"Datentypen":"نوع‌های داده","Zahlen, Text und Boolean unterscheiden":"عدد، متن و Boolean را از هم جدا کنید","Zahlen ohne Anführungszeichen":"عددها بدون علامهٔ نقل‌قول","Eine Zahl wie 12 lässt sich direkt berechnen. Ohne Anführungszeichen speichert JavaScript einen numerischen Wert. Für einen festen Preis ist const geeignet. Ein Preisetikett trägt eine Zahl, nicht den geschriebenen Namen der Zahl.":"عددی مثل 12 را می‌شود مستقیم حساب کرد. بدون علامهٔ نقل‌قول، JavaScript یک مقدار عددی نگه می‌دارد. برای یک قیمت ثابت const مناسب است. یک برچسب قیمت یک عدد دارد، نه نام نوشته‌شدهٔ آن عدد را.","Zeile 1 legt preis mit `const` fest; Zeile 2 legt ort als Zeichenkette an. Vergleiche `12 + 3` mit `'12' + 3` und beobachte `15` gegenüber `123`.":"خط 1 ‏preis را با `const` تعیین می‌کند؛ خط 2 ‏ort را به شکل رشتهٔ متنی می‌سازد. `12 + 3` را با `'12' + 3` مقایسه کنید و `15` را در برابر `123` ببینید.","Strings als Textwerte":"String به عنوان مقدار متنی","Ein Ortsname wird als String gespeichert. Dafür schreibst du den Text zwischen Anführungszeichen. Mit einem Pluszeichen lassen sich zwei Strings verbinden. Eine Postkarte enthält Buchstaben und wird nicht wie ein Geldbetrag addiert. `const ort = 'Bonn';` bindet den Text Bonn an den Namen ort. `console.log(ort)` schreibt diesen Text in die Entwicklerkonsole. Setze statt Bonn deinen eigenen Wohnort ein und behalte die Anführungszeichen.":"نام یک جا به شکل String نگه داشته می‌شود. برای این کار متن را بین علامهٔ نقل‌قول می‌نویسید. با علامهٔ جمع می‌شود دو String را به هم وصل کرد. یک کارت پستال حروف دارد و مثل یک مبلغ پول جمع زده نمی‌شود. `const ort = 'Bonn';` متن Bonn را به نام ort وصل می‌کند. `console.log(ort)` این متن را در کنسول توسعه‌دهنده می‌نویسد. به جای Bonn نام شهر خودتان را بگذارید و علامهٔ نقل‌قول را نگه دارید.","`const ort = 'Bonn';` bindet den Text Bonn an den Namen ort. `console.log(ort)` schreibt diesen Text in die Entwicklerkonsole.":"`const ort = 'Bonn';` متن Bonn را به نام ort وصل می‌کند. `console.log(ort)` این متن را در کنسول توسعه‌دهنده می‌نویسد.","Boolean true und false":"Boolean ‏true و false","Ein Boolean ist entweder true oder false. Er steht ohne Anführungszeichen im Code. So kannst du Zustände wie offen oder geschlossen speichern. Ein Lichtschalter hat zwei Zustände; Boolean bildet genau diese Unterscheidung ab.":"یک Boolean یا true است یا false. بدون علامهٔ نقل‌قول در کد نوشته می‌شود. به این ترتیب می‌توانید وضعیت‌هایی مثل باز یا بسته را نگه دارید. یک سویچ چراغ دو وضعیت دارد؛ Boolean دقیقاً همین تفاوت را نشان می‌دهد.","`const offen = true;` legt einen echten Wahrheitswert an. `if (offen)` kann damit eine Entscheidung treffen, ohne Text zu vergleichen.":"`const offen = true;` یک مقدار درست/نادرست واقعی می‌سازد. `if (offen)` با آن می‌تواند تصمیم بگیرد، بدون اینکه متن را مقایسه کند.","Mit typeof kontrollieren":"بررسی با typeof","typeof zeigt den Typ eines Werts an. typeof 12 liefert number, typeof '12' liefert string. Teste den Unterschied in der Konsole. Ein Etikett am Vorratsglas sagt dir, was darin liegt; `typeof` übernimmt diese Aufgabe für Werte. `console.log(typeof 12);` zeigt `number` als Typ an. `console.log(typeof '12');` zeigt `string`, obwohl die Zeichen gleich aussehen. Notiere beide Ergebnisse, bevor du weitere Werte ausprobierst.":"typeof نوع یک مقدار را نشان می‌دهد. typeof 12 نتیجهٔ number و typeof '12' نتیجهٔ string می‌دهد. این تفاوت را در کنسول آزمایش کنید. برچسب روی یک شیشهٔ ذخیره به شما می‌گوید داخلش چیست؛ `typeof` همین کار را برای مقدارها می‌کند. `console.log(typeof 12);` ‏`number` را به عنوان نوع نشان می‌دهد. `console.log(typeof '12');` ‏`string` را نشان می‌دهد، با اینکه حروف یکسان به نظر می‌رسند. هر دو نتیجه را یادداشت کنید، پیش از اینکه مقدارهای دیگر را امتحان کنید.","`console.log(typeof 12);` zeigt `number` als Typ an. `console.log(typeof '12');` zeigt `string`, obwohl die Zeichen gleich aussehen.":"`console.log(typeof 12);` ‏`number` را به عنوان نوع نشان می‌دهد. `console.log(typeof '12');` ‏`string` را نشان می‌دهد، با اینکه حروف یکسان به نظر می‌رسند.","Zahl als Text gespeichert":"عدد به شکل متن نگه داشته شد","Falsch: `const preis = '12'; console.log(preis + 3);` ergibt `123` statt `15` in der Konsole. Der Preis ist ein String und das Pluszeichen hängt Text an. Richtig: `const preis = 12; console.log(preis + 3);` zeigt `15`.":"اشتباه: `const preis = '12'; console.log(preis + 3);` در کنسول به جای `15` نتیجهٔ `123` می‌دهد. قیمت یک String است و علامهٔ جمع متن را می‌چسپاند. درست: `const preis = 12; console.log(preis + 3);` ‏`15` را نشان می‌دهد.","Boolean fälschlich in Anführungszeichen":"Boolean به اشتباه در علامهٔ نقل‌قول","Falsch: `const offen = 'false'; if (offen) console.log('offen');` zeigt trotzdem `offen`, weil der nichtleere String als wahr gilt. Richtig: `const offen = false; if (offen) console.log('offen');` zeigt keine Meldung.":"اشتباه: `const offen = 'false'; if (offen) console.log('offen');` با این حال `offen` را نشان می‌دهد، چون یک String غیرخالی درست حساب می‌شود. درست: `const offen = false; if (offen) console.log('offen');` هیچ پیامی نشان نمی‌دهد.","Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.":"مثال را در ویرایشگر به کار ببرید و پیش‌نمایش یا کنسول را بررسی کنید.","Vergleiche die Schreibweise mit dem Codebeispiel.":"املا را با مثال کد مقایسه کنید.","Passende HTML-Struktur vorhanden.":"ساختار مناسب HTML وجود دارد.","JavaScript enthält die geübte Technik.":"JavaScript تکنیک تمرین‌شده را دارد.","Was ist typeof 12?":"typeof 12 چیست؟","Hier passt „number“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „number“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Diese Antwort beschreibt nicht die gesuchte Funktion.":"این جواب کار خواسته‌شده را توصیف نمی‌کند.","Diese Antwort beschreibt die gesuchte Funktion.":"این جواب کار خواسته‌شده را توصیف می‌کند.","Was ist typeof '12'?":"typeof '12' چیست؟","Hier passt „string“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „string“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Welcher Wert ist ein Boolean?":"کدام مقدار یک Boolean است؟","Hier passt „true“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „true“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Bei Datentypen ist die genaue JavaScript-Schreibweise wichtig.":"در نوع‌های داده، املای دقیق JavaScript مهم است.","Nutze die Lösung `const preis = 12; const ort = 'Bonn'; const offen = true;` als Vergleich für deine eigene Übung.":"از راه‌حل `const preis = 12; const ort = 'Bonn'; const offen = true;` برای مقایسه با تمرین خودتان استفاده کنید.","Arrays":"آرایه‌ها","Mehrere Einträge in einer Liste speichern":"چند عنصر را در یک لست نگه دارید","Eine Einkaufsliste anlegen":"ساختن یک لست خرید","Ein Array sammelt mehrere Werte in eckigen Klammern. Trenne die Einträge mit Kommas. So bleibt eine Einkaufsliste in einer einzigen Variablen. Eine Einkaufstasche enthält mehrere Produkte; ein Array hält ihre Namen zusammen.":"یک آرایه چند مقدار را داخل قوس‌های چهارگوش جمع می‌کند. عنصرها را با کامه جدا کنید. به این ترتیب یک لست خرید در یک متغیر واحد می‌ماند. یک خریطهٔ خرید چند جنس دارد؛ یک آرایه نام‌های آن‌ها را یک‌جا نگه می‌دارد.","`const einkauf = ['Brot', 'Milch'];` erzeugt zwei Einträge. Die eckigen Klammern gehören zur Liste, die Anführungszeichen zu jedem Text.":"`const einkauf = ['Brot', 'Milch'];` دو عنصر می‌سازد. قوس‌های چهارگوش به لست تعلق دارند و علامهٔ نقل‌قول به هر متن.","Einträge mit Index lesen":"خواندن عنصرها با شاخص","Die erste Position eines Arrays hat den Index null. einkauf[0] liefert daher Brot. Der zweite Eintrag wird über einkauf[1] gelesen. Regalfächer haben Nummern; JavaScript beginnt die Nummerierung bei null. `console.log(einkauf[0]);` liest Brot aus dem ersten Fach. `console.log(einkauf[1]);` liest Milch aus dem zweiten Fach. Ein Zugriff auf `einkauf[9]` liefert dagegen `undefined`.":"اولین جایگاه یک آرایه شاخص صفر دارد. به همین دلیل einkauf[0] ‏Brot را می‌دهد. عنصر دوم با einkauf[1] خوانده می‌شود. خانه‌های الماری شماره دارند؛ JavaScript شمارش را از صفر شروع می‌کند. `console.log(einkauf[0]);` ‏Brot را از خانهٔ اول می‌خواند. `console.log(einkauf[1]);` ‏Milch را از خانهٔ دوم می‌خواند. اما دسترسی به `einkauf[9]` نتیجهٔ `undefined` می‌دهد.","`console.log(einkauf[0]);` liest Brot aus dem ersten Fach. `console.log(einkauf[1]);` liest Milch aus dem zweiten Fach.":"`console.log(einkauf[0]);` ‏Brot را از خانهٔ اول می‌خواند. `console.log(einkauf[1]);` ‏Milch را از خانهٔ دوم می‌خواند.","Mit push erweitern":"گسترش با push","Mit push fügst du einen neuen Eintrag am Ende hinzu. Die vorhandenen Werte bleiben erhalten. Probiere einkauf.push('Reis') in deinem Beispiel aus. Beim Einkaufen legst du neue Waren hinten in die Tasche; so arbeitet push. `einkauf.push('Reis');` ergänzt den String Reis. `console.log(einkauf);` zeigt danach alle drei Namen. Die Methode braucht runde Klammern und den gewünschten Wert.":"با push یک عنصر تازه را به آخر اضافه می‌کنید. مقدارهای موجود باقی می‌مانند. einkauf.push('Reis') را در مثال خود امتحان کنید. هنگام خرید جنس‌های تازه را در آخر خریطه می‌گذارید؛ push همین‌طور کار می‌کند. `einkauf.push('Reis');` ‏String ‏Reis را اضافه می‌کند. `console.log(einkauf);` بعد از آن هر سه نام را نشان می‌دهد. این متود به قوس‌های گرد و مقدار دلخواه نیاز دارد.","`einkauf.push('Reis');` ergänzt den String Reis. `console.log(einkauf);` zeigt danach alle drei Namen.":"`einkauf.push('Reis');` ‏String ‏Reis را اضافه می‌کند. `console.log(einkauf);` بعد از آن هر سه نام را نشان می‌دهد.","Die Länge abfragen":"پرسیدن طول","length gibt die Anzahl der Einträge zurück. Nach dem Hinzufügen sind es drei. Verwende die Eigenschaft ohne Klammern. Ein Kassenbon zählt Positionen, nicht den letzten Regalindex. `console.log(einkauf.length);` liefert nach push den Wert drei. Die Eigenschaft length wird ohne `()` geschrieben. Lösche testweise einen Eintrag und vergleiche die neue Anzahl.":"length تعداد عنصرها را می‌دهد. بعد از اضافه کردن، سه عنصر است. این ویژگی را بدون قوس به کار ببرید. یک رسید خرید ردیف‌ها را می‌شمارد، نه آخرین شاخص الماری را. `console.log(einkauf.length);` بعد از push مقدار سه را می‌دهد. ویژگی length بدون `()` نوشته می‌شود. به‌طور آزمایشی یک عنصر را پاک کنید و تعداد تازه را مقایسه کنید.","`console.log(einkauf.length);` liefert nach push den Wert drei. Die Eigenschaft length wird ohne `()` geschrieben.":"`console.log(einkauf.length);` بعد از push مقدار سه را می‌دهد. ویژگی length بدون `()` نوشته می‌شود.","Ersten Eintrag mit Index eins gesucht":"عنصر اول با شاخص یک جستجو شد","Falsch: `console.log(einkauf[1]);` zeigt `Milch`, obwohl du `Brot` erwartest. Arrays zählen ab null. Richtig: `console.log(einkauf[0]);` zeigt `Brot`.":"اشتباه: `console.log(einkauf[1]);` ‏`Milch` را نشان می‌دهد، با اینکه شما `Brot` را انتظار دارید. آرایه‌ها از صفر می‌شمارند. درست: `console.log(einkauf[0]);` ‏`Brot` را نشان می‌دهد.","push ohne Argument verwendet":"push بدون مقدار به کار رفت","Falsch: `einkauf.push();` fügt einen Eintrag mit dem Wert `undefined` hinzu; die Liste enthält danach keinen neuen Artikelnamen. Richtig: `einkauf.push('Reis');` ergänzt einen sichtbaren Einkauf.":"اشتباه: `einkauf.push();` یک عنصر با مقدار `undefined` اضافه می‌کند؛ لست بعد از آن هیچ نام جنس تازه‌ای ندارد. درست: `einkauf.push('Reis');` یک خرید قابل دید اضافه می‌کند.","Welcher Index ist der erste?":"کدام شاخص اولین است؟","Hier passt „0“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „0“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Wie wird Reis angehängt?":"Reis چطور اضافه می‌شود؟","Hier passt „einkauf.push('Reis')“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „einkauf.push('Reis')“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was liefert length?":"length چه می‌دهد؟","Anzahl der Einträge":"تعداد عنصرها","Ersten Text":"اولین متن","Letzten Namen":"آخرین نام","Hier passt „Anzahl der Einträge“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „تعداد عنصرها“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Bei Arrays ist die genaue JavaScript-Schreibweise wichtig.":"در آرایه‌ها، املای دقیق JavaScript مهم است.","Nutze die Lösung `const einkauf = ['Brot','Milch']; einkauf.push('Reis'); console.log(einkauf.length);` als Vergleich für deine eigene Übung.":"از راه‌حل `const einkauf = ['Brot','Milch']; einkauf.push('Reis'); console.log(einkauf.length);` برای مقایسه با تمرین خودتان استفاده کنید.","Schleifen":"حلقه‌ها","Wiederholungen mit for und for...of schreiben":"تکرارها را با for و for...of بنویسید","Wiederholung verstehen":"فهمیدن تکرار","Eine Schleife führt denselben Ablauf mehrmals aus. Du musst die Anweisung nicht kopieren. Das ist bei einer Liste von Namen besonders praktisch. Eine Lehrkraft ruft alle Namen der Anwesenheitsliste nacheinander auf.":"یک حلقه یک روند را چند بار اجرا می‌کند. لازم نیست دستور را کاپی کنید. این برای یک لست نام‌ها به‌خصوص کاربردی است. یک معلم همهٔ نام‌های لست حاضری را یکی پس از دیگری صدا می‌زند.","`for (const name of namen)` besucht jeden vorhandenen Eintrag. Der Block in geschweiften Klammern wird für jeden Namen wiederholt.":"`for (const name of namen)` به هر عنصر موجود سر می‌زند. بلاک داخل قوس‌های گُل‌دار برای هر نام تکرار می‌شود.","for...of für Arrays":"for...of برای آرایه‌ها","for...of liest die Einträge nacheinander. Der Name im Schleifenkopf steht jeweils für den aktuellen Eintrag. Innerhalb der Klammern kannst du ihn ausgeben. Wie bei einer Runde durch mehrere Zimmer wird derselbe Arbeitsschritt wiederholt. `console.log(name);` verwendet im Block den jeweils aktuellen Namen. Nach dem letzten Eintrag endet for...of automatisch. Prüfe die Ausgabe mit einer Liste aus drei Personen.":"for...of عنصرها را یکی پس از دیگری می‌خواند. نام در سر حلقه هر بار به معنای عنصر فعلی است. داخل قوس‌ها می‌توانید آن را نشان دهید. مثل یک دور در چند اتاق، یک کار تکرار می‌شود. `console.log(name);` در بلاک هر بار نام فعلی را به کار می‌برد. بعد از آخرین عنصر، for...of خودکار تمام می‌شود. خروجی را با یک لست سه نفره بررسی کنید.","`console.log(name);` verwendet im Block den jeweils aktuellen Namen. Nach dem letzten Eintrag endet for...of automatisch.":"`console.log(name);` در بلاک هر بار نام فعلی را به کار می‌برد. بعد از آخرین عنصر، for...of خودکار تمام می‌شود.","Zähler mit let verwenden":"استفاده از شمارنده با let","Eine klassische for-Schleife benutzt oft let i = 0. Nach jedem Durchlauf erhöht i++ den Zähler. Mit i < 3 läuft der Block genau dreimal. Eine Nummernausgabe am Schalter zählt 0, 1, 2 und stoppt dann.":"یک حلقهٔ for کلاسیک اغلب let i = 0 را به کار می‌برد. بعد از هر دور i++ شمارنده را زیاد می‌کند. با i < 3 بلاک دقیقاً سه بار اجرا می‌شود. یک دستگاه نوبت در کاونتر 0، 1، 2 می‌شمارد و بعد می‌ایستد.","`let i = 0` setzt den Anfangswert, `i < 3` prüft die Grenze. `i++` erhöht die Nummer nach jedem Durchlauf um eins.":"`let i = 0` مقدار شروع را می‌گذارد و `i < 3` حد را بررسی می‌کند. `i++` بعد از هر دور شماره را یکی زیاد می‌کند.","Abbruchbedingung prüfen":"بررسی شرط توقف","Eine Schleife braucht eine erreichbare Abbruchbedingung. Ohne Änderung des Zählers kann sie endlos laufen. Prüfe den Ablauf zunächst mit wenigen Werten. Eine Rolltreppe ohne Ausgang wäre gefährlich; eine Schleife ohne Ende blockiert den Ablauf.":"یک حلقه به یک شرط توقف قابل رسیدن نیاز دارد. بدون تغییر شمارنده ممکن است بی‌پایان اجرا شود. روند را اول با چند مقدار کم بررسی کنید. یک زینهٔ برقی بدون خروجی خطرناک می‌بود؛ یک حلقهٔ بی‌پایان روند را متوقف می‌کند.","Bei `for (let i = 0; i < 3; i++)` ist das Ende erreichbar. Wenn `i++` fehlt, bleibt die Bedingung dauerhaft wahr.":"در `for (let i = 0; i < 3; i++)` پایان قابل رسیدن است. اگر `i++` نباشد، شرط همیشه درست می‌ماند.","Zähler wird nicht erhöht":"شمارنده زیاد نمی‌شود","Falsch: `for (let i = 0; i < 3;) console.log(i);` bleibt bei null und kann den Browser blockieren. Der Zähler ändert sich nie. Richtig: `for (let i = 0; i < 3; i++) console.log(i);` gibt `0`, `1`, `2` aus.":"اشتباه: `for (let i = 0; i < 3;) console.log(i);` در صفر می‌ماند و ممکن است براوزر را متوقف کند. شمارنده هرگز تغییر نمی‌کند. درست: `for (let i = 0; i < 3; i++) console.log(i);` ‏`0`، `1`، `2` را نشان می‌دهد.","Index läuft über das Arrayende":"شاخص از آخر آرایه می‌گذرد","Falsch: `for (let i = 0; i <= namen.length; i++) console.log(namen[i]);` gibt am Ende `undefined` aus. Der letzte gültige Index ist kleiner als length. Richtig: `for (let i = 0; i < namen.length; i++) console.log(namen[i]);`.":"اشتباه: `for (let i = 0; i <= namen.length; i++) console.log(namen[i]);` در آخر `undefined` نشان می‌دهد. آخرین شاخص معتبر از length کوچک‌تر است. درست: `for (let i = 0; i < namen.length; i++) console.log(namen[i]);`.","Was macht for...of?":"for...of چه کار می‌کند؟","Löscht Elemente":"عنصرها را پاک می‌کند","Liest Einträge nacheinander":"عنصرها را یکی پس از دیگری می‌خواند","Öffnet eine Webseite":"یک ویب‌سایت را باز می‌کند","Hier passt „Liest Einträge nacheinander“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „عنصرها را یکی پس از دیگری می‌خواند“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Wie viele Durchläufe hat i < 3 ab null?":"i < 3 از صفر چند دور دارد؟","Drei":"سه","Vier":"چهار","Zwei":"دو","Hier passt „Drei“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „سه“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was vermeidet eine Endlosschleife?":"چه چیزی از حلقهٔ بی‌پایان جلوگیری می‌کند؟","Längere Namen":"نام‌های طولانی‌تر","Mehr Farben":"رنگ‌های بیشتر","Erreichbare Abbruchbedingung":"شرط توقف قابل رسیدن","Hier passt „Erreichbare Abbruchbedingung“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „شرط توقف قابل رسیدن“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Bei Schleifen ist die genaue JavaScript-Schreibweise wichtig.":"در حلقه‌ها، املای دقیق JavaScript مهم است.","Nutze die Lösung `const namen = ['Ali','Mina']; for (const name of namen) { console.log(name); }` als Vergleich für deine eigene Übung.":"از راه‌حل `const namen = ['Ali','Mina']; for (const name of namen) { console.log(name); }` برای مقایسه با تمرین خودتان استفاده کنید.","Funktionen":"تابع‌ها","Eigene Funktionen mit Parametern und return nutzen":"تابع‌های خودتان را با پارامتر و return به کار ببرید","Funktion benennen":"نام دادن به تابع","Eine Funktion bündelt einen wiederkehrenden Ablauf. function leitet die Definition ein. Der Name beschreibt die Aufgabe möglichst genau. Eine Kaffeemaschine erledigt nach dem Start immer dieselben Schritte.":"یک تابع یک روند تکراری را یک‌جا جمع می‌کند. function تعریف را شروع می‌کند. نام باید کار را تا حد ممکن دقیق توصیف کند. یک ماشین قهوه بعد از روشن شدن همیشه همان قدم‌ها را انجام می‌دهد.","`function doppelt(zahl)` gibt dem Ablauf einen Namen und einen Parameter. Die geschweiften Klammern umschließen die Rechenanweisung.":"`function doppelt(zahl)` به روند یک نام و یک پارامتر می‌دهد. قوس‌های گُل‌دار دستور حساب را در بر می‌گیرند.","Parameter entgegennehmen":"گرفتن پارامترها","In runden Klammern stehen Parameter. Beim Aufruf wird für jeden Parameter ein Wert übergeben. Im Funktionskörper kannst du damit rechnen. Eine Bestellung nennt die gewünschte Menge; ein Parameter übernimmt diesen Wert.":"داخل قوس‌های گرد پارامترها هستند. هنگام صدا زدن برای هر پارامتر یک مقدار داده می‌شود. در بدنهٔ تابع می‌توانید با آن حساب کنید. یک سفارش مقدار دلخواه را نام می‌برد؛ یک پارامتر این مقدار را می‌گیرد.","`doppelt(4)` übergibt die Zahl vier an den Parameter zahl. Im Funktionskörper steht dann für zahl genau dieser Wert.":"`doppelt(4)` عدد چهار را به پارامتر zahl می‌دهد. در بدنهٔ تابع به جای zahl دقیقاً همین مقدار قرار می‌گیرد.","Ergebnis zurückgeben":"پس دادن نتیجه","return liefert ein Ergebnis an den Aufrufer. Eine reine Konsolenausgabe gibt dagegen nicht automatisch einen Wert zurück. Nutze return für weitere Berechnungen. Ein Automat gibt nach dem Einwurf etwas zurück; return ist diese Rückgabe. `return zahl * 2;` berechnet und liefert das Ergebnis. `console.log` kann es anschließend sichtbar machen, ersetzt return aber nicht. Ohne return erhält der Aufrufer den Wert `undefined`.":"return یک نتیجه را به صدازننده می‌دهد. اما یک خروجی کنسول به تنهایی خودکار مقداری پس نمی‌دهد. return را برای حساب‌های بعدی به کار ببرید. یک ماشین فروش بعد از انداختن سکه چیزی پس می‌دهد؛ return همین پس دادن است. `return zahl * 2;` نتیجه را حساب می‌کند و می‌دهد. `console.log` بعد از آن می‌تواند آن را نشان دهد، اما جای return را نمی‌گیرد. بدون return صدازننده مقدار `undefined` را می‌گیرد.","`return zahl * 2;` berechnet und liefert das Ergebnis. `console.log` kann es anschließend sichtbar machen, ersetzt return aber nicht.":"`return zahl * 2;` نتیجه را حساب می‌کند و می‌دهد. `console.log` بعد از آن می‌تواند آن را نشان دهد، اما جای return را نمی‌گیرد.","Funktion aufrufen":"صدا زدن تابع","Die Definition allein führt den Code noch nicht aus. Erst doppelt(4) startet den Ablauf. Das Ergebnis dieser Rechnung ist acht. Ein beschrifteter Werkzeugkasten lässt dich ein Werkzeug schnell wiederfinden. Der Name doppelt beschreibt die Rechnung besser als ein beliebiger Buchstabe. `console.log(doppelt(4));` startet den Aufruf und zeigt acht. Verwende denselben Funktionsnamen beim Definieren und Aufrufen.":"تعریف به تنهایی کد را اجرا نمی‌کند. فقط doppelt(4) روند را شروع می‌کند. نتیجهٔ این حساب هشت است. یک جعبهٔ ابزار برچسب‌دار به شما کمک می‌کند یک ابزار را زود پیدا کنید. نام doppelt حساب را بهتر از یک حرف دلخواه توصیف می‌کند. `console.log(doppelt(4));` صدا زدن را شروع می‌کند و هشت را نشان می‌دهد. هنگام تعریف و صدا زدن یک نام تابع را به کار ببرید.","Der Name doppelt beschreibt die Rechnung besser als ein beliebiger Buchstabe. `console.log(doppelt(4));` startet den Aufruf und zeigt acht.":"نام doppelt حساب را بهتر از یک حرف دلخواه توصیف می‌کند. `console.log(doppelt(4));` صدا زدن را شروع می‌کند و هشت را نشان می‌دهد.","Funktion nicht aufgerufen":"تابع صدا زده نشد","Falsch: `function doppelt(x) { return x * 2; }` allein erzeugt keine Ausgabe; die Funktion wurde noch nicht gestartet. Richtig: `console.log(doppelt(4));` ruft sie auf und zeigt `8`.":"اشتباه: `function doppelt(x) { return x * 2; }` به تنهایی خروجی ندارد؛ تابع هنوز شروع نشده است. درست: `console.log(doppelt(4));` آن را صدا می‌زند و `8` را نشان می‌دهد.","console.log mit return verwechselt":"اشتباه گرفتن console.log با return","Falsch: `function doppelt(x) { console.log(x * 2); } console.log(doppelt(4));` zeigt zuerst `8`, dann `undefined`. console.log zeigt nur etwas an, gibt aber keinen Rückgabewert zurück. Richtig: `function doppelt(x) { return x * 2; } console.log(doppelt(4));` zeigt nur `8`.":"اشتباه: `function doppelt(x) { console.log(x * 2); } console.log(doppelt(4));` اول `8` و بعد `undefined` را نشان می‌دهد. console.log فقط چیزی را نشان می‌دهد، اما مقدار بازگشتی نمی‌دهد. درست: `function doppelt(x) { return x * 2; } console.log(doppelt(4));` فقط `8` را نشان می‌دهد.","Wozu dient ein Parameter?":"پارامتر برای چیست؟","Zum Löschen":"برای پاک کردن","Für Eingabewerte":"برای مقدارهای ورودی","Für CSS":"برای CSS","Hier passt „Für Eingabewerte“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „برای مقدارهای ورودی“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was macht return?":"return چه کار می‌کند؟","Gibt ein Ergebnis zurück":"یک نتیجه پس می‌دهد","Startet HTML":"HTML را شروع می‌کند","Öffnet eine Datei":"یک فایل را باز می‌کند","Hier passt „Gibt ein Ergebnis zurück“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „یک نتیجه پس می‌دهد“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Wann läuft die Funktion?":"تابع چه وقت اجرا می‌شود؟","Beim Speichern":"هنگام ذخیره","Beim Benennen":"هنگام نام دادن","Beim Aufruf":"هنگام صدا زدن","Hier passt „Beim Aufruf“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „هنگام صدا زدن“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Bei Funktionen ist die genaue JavaScript-Schreibweise wichtig.":"در تابع‌ها، املای دقیق JavaScript مهم است.","Nutze die Lösung `function doppelt(zahl) { return zahl * 2; } console.log(doppelt(4));` als Vergleich für deine eigene Übung.":"از راه‌حل `function doppelt(zahl) { return zahl * 2; } console.log(doppelt(4));` برای مقایسه با تمرین خودتان استفاده کنید.","Objekte":"آبجکت‌ها","Zusammengehörige Eigenschaften verwalten":"ویژگی‌های مربوط به هم را مدیریت کنید","Personendaten bündeln":"جمع کردن معلومات یک شخص","Ein Objekt speichert zusammengehörige Angaben. Zwischen geschweiften Klammern stehen Eigenschaft und Wert. Ein Doppelpunkt trennt beide Teile. Eine Kontaktkarte hält Name und Ort einer Person beisammen.":"یک آبجکت معلومات مربوط به هم را نگه می‌دارد. بین قوس‌های گُل‌دار ویژگی و مقدار می‌آیند. یک دونقطه هر دو بخش را جدا می‌کند. یک کارت تماس نام و شهر یک شخص را کنار هم نگه می‌دارد.","`const person = { name: 'Amina', ort: 'Bonn' };` erstellt zwei Eigenschaften. Der Doppelpunkt verbindet jeweils Schlüssel und Wert.":"`const person = { name: 'Amina', ort: 'Bonn' };` دو ویژگی می‌سازد. دونقطه هر بار کلید و مقدار را به هم وصل می‌کند.","Eigenschaften mit Punkt lesen":"خواندن ویژگی‌ها با نقطه","Mit person.name liest du eine Eigenschaft. Du brauchst dafür keine zusätzliche Variable. Der Punkt verbindet den Objektnamen mit dem Eigenschaftsnamen. Auf einer Karte suchst du die Zeile Name, nicht die ganze Karte. `person.name` liest nur den gespeicherten Namen. `console.log(person.name);` zeigt ihn in der Konsole. Schreibst du versehentlich Name groß, erhältst du möglicherweise undefined.":"با person.name یک ویژگی را می‌خوانید. برای این کار به متغیر اضافی نیاز ندارید. نقطه نام آبجکت را با نام ویژگی وصل می‌کند. روی یک کارت دنبال ردیف نام می‌گردید، نه تمام کارت. `person.name` فقط نام ذخیره‌شده را می‌خواند. `console.log(person.name);` آن را در کنسول نشان می‌دهد. اگر به اشتباه Name را با حرف بزرگ بنویسید، شاید undefined بگیرید.","`person.name` liest nur den gespeicherten Namen. `console.log(person.name);` zeigt ihn in der Konsole.":"`person.name` فقط نام ذخیره‌شده را می‌خواند. `console.log(person.name);` آن را در کنسول نشان می‌دهد.","Eigenschaften ändern":"تغییر ویژگی‌ها","Eine Eigenschaft lässt sich mit person.ort = 'Köln' ändern. Das ist auch bei einem mit const angelegten Objekt erlaubt. Die gesamte Variable darf jedoch nicht neu zugewiesen werden. Eine Adresse auf einer Kontaktkarte darf sich nach einem Umzug ändern. `person.ort = 'Köln';` ersetzt nur den Wert der Eigenschaft ort. Die Variable person bleibt weiterhin dasselbe Objekt. Prüfe die Änderung mit einer anschließenden Konsolenausgabe.":"یک ویژگی را می‌شود با person.ort = 'Köln' تغییر داد. این کار در آبجکتی که با const ساخته شده هم مجاز است. اما تمام متغیر را نمی‌شود دوباره مقدار داد. آدرس روی یک کارت تماس بعد از کوچ کردن می‌تواند تغییر کند. `person.ort = 'Köln';` فقط مقدار ویژگی ort را عوض می‌کند. متغیر person همچنان همان آبجکت می‌ماند. تغییر را با یک خروجی کنسول بعدی بررسی کنید.","`person.ort = 'Köln';` ersetzt nur den Wert der Eigenschaft ort. Die Variable person bleibt weiterhin dasselbe Objekt.":"`person.ort = 'Köln';` فقط مقدار ویژگی ort را عوض می‌کند. متغیر person همچنان همان آبجکت می‌ماند.","Fehlende Werte erkennen":"شناختن مقدارهای ناموجود","Ein falsch geschriebener Eigenschaftsname liefert oft undefined. Prüfe die genaue Schreibweise. Gleiche Namen machen mehrere Objekte leichter vergleichbar. Fehlt ein Feld auf einer Karte, kannst du seinen Inhalt nicht lesen. `person.alter` liefert undefined, wenn alter nicht existiert. Prüfe die Schreibweise der Eigenschaft vor weiteren Berechnungen. Du kannst `person.alter = 30` ergänzen und danach erneut lesen.":"یک نام ویژگی که اشتباه نوشته شود اغلب undefined می‌دهد. املای دقیق را بررسی کنید. نام‌های یکسان مقایسهٔ چند آبجکت را آسان‌تر می‌کنند. اگر یک خانه روی کارت نباشد، نمی‌توانید محتوای آن را بخوانید. `person.alter` وقتی alter وجود نداشته باشد undefined می‌دهد. املای ویژگی را پیش از حساب‌های بعدی بررسی کنید. می‌توانید `person.alter = 30` را اضافه کنید و بعد دوباره بخوانید.","`person.alter` liefert undefined, wenn alter nicht existiert. Prüfe die Schreibweise der Eigenschaft vor weiteren Berechnungen.":"`person.alter` وقتی alter وجود نداشته باشد undefined می‌دهد. املای ویژگی را پیش از حساب‌های بعدی بررسی کنید.","Eigenschaftsname falsch geschrieben":"نام ویژگی اشتباه نوشته شد","Falsch: `console.log(person.Name);` liefert `undefined`, obwohl `name` gespeichert ist. Eigenschaftsnamen unterscheiden Groß- und Kleinschreibung. Richtig: `console.log(person.name);` zeigt `Amina`.":"اشتباه: `console.log(person.Name);` ‏`undefined` می‌دهد، با اینکه `name` ذخیره شده است. نام ویژگی‌ها بین حروف بزرگ و کوچک فرق می‌گذارند. درست: `console.log(person.name);` ‏`Amina` را نشان می‌دهد.","const-Objekt neu zugewiesen":"آبجکت const دوباره مقدار گرفت","Falsch: `const person = { name: 'Amina' }; person = { name: 'Mina' };` erzeugt `TypeError: Assignment to constant variable.`. Du darfst die const-Bindung nicht ersetzen. Richtig: `person.name = 'Mina';` ändert die Eigenschaft.":"اشتباه: `const person = { name: 'Amina' }; person = { name: 'Mina' };` خطای `TypeError: Assignment to constant variable.` می‌دهد. اجازه ندارید پیوند const را عوض کنید. درست: `person.name = 'Mina';` ویژگی را تغییر می‌دهد.","Was liefert person.name?":"person.name چه می‌دهد؟","Ort":"شهر","Name":"نام","Objektlänge":"طول آبجکت","Hier passt „Name“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „نام“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was bedeutet undefined?":"undefined یعنی چه؟","Wert fehlt möglicherweise":"شاید مقدار وجود ندارد","Alles ist gelöscht":"همه چیز پاک شده است","Wert ist null":"مقدار null است","Hier passt „Wert fehlt möglicherweise“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „شاید مقدار وجود ندارد“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was darfst du ändern?":"چه چیزی را اجازه دارید تغییر دهید؟","const person neu setzen":"دوباره مقدار دادن به const person","const entfernen":"برداشتن const","Hier passt „person.ort“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „person.ort“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Bei Objekte ist die genaue JavaScript-Schreibweise wichtig.":"در آبجکت‌ها، املای دقیق JavaScript مهم است.","Nutze die Lösung `const person = { name: 'Amina', ort: 'Bonn' }; console.log(person.name);` als Vergleich für deine eigene Übung.":"از راه‌حل `const person = { name: 'Amina', ort: 'Bonn' }; console.log(person.name);` برای مقایسه با تمرین خودتان استفاده کنید.","HTML-Elemente finden und sicher verändern":"عنصرهای HTML را پیدا کنید و مطمئن تغییر دهید","DOM als Dokumentstruktur":"DOM به عنوان ساختار سند","Der Browser stellt HTML als Dokumentstruktur bereit. Diese Struktur heißt DOM. JavaScript kann darin gezielt Elemente suchen. Ein Stadtplan zeigt Straßen und Häuser; das DOM bildet die Struktur einer Webseite ab. `document.querySelector('#ausgabe')` sucht die passende ID. Das Zeichen # bedeutet, dass du ein bestimmtes Element meinst. Lege ein `<p id='ausgabe'>` an, damit die Suche erfolgreich ist.":"براوزر HTML را به شکل یک ساختار سند فراهم می‌کند. به این ساختار DOM می‌گویند. JavaScript می‌تواند در آن هدفمند دنبال عنصرها بگردد. یک نقشهٔ شهر سرک‌ها و خانه‌ها را نشان می‌دهد؛ DOM ساختار یک ویب‌سایت را نشان می‌دهد. `document.querySelector('#ausgabe')` دنبال ID مناسب می‌گردد. علامهٔ # یعنی شما یک عنصر معین را منظور دارید. یک `<p id='ausgabe'>` بسازید تا جستجو موفق باشد.","`document.querySelector('#ausgabe')` sucht die passende ID. Das Zeichen # bedeutet, dass du ein bestimmtes Element meinst.":"`document.querySelector('#ausgabe')` دنبال ID مناسب می‌گردد. علامهٔ # یعنی شما یک عنصر معین را منظور دارید.","Element per ID auswählen":"انتخاب عنصر با ID","querySelector findet ein Element anhand eines CSS-Selektors. Das Zeichen # steht für eine ID. Stimmen die Namen nicht überein, kommt null zurück. Eine Hausnummer muss genau stimmen, sonst findest du das Gebäude nicht. `const ausgabe = document.querySelector('#ausgabe');` speichert das gefundene Element. Ist die ID anders geschrieben, steht in ausgabe der Wert null. Prüfe den Namen im HTML und im JavaScript Zeichen für Zeichen.":"querySelector یک عنصر را بر اساس یک انتخابگر CSS پیدا می‌کند. علامهٔ # برای یک ID است. اگر نام‌ها جور نیایند، null برمی‌گردد. یک شمارهٔ خانه باید دقیقاً درست باشد، وگرنه ساختمان را پیدا نمی‌کنید. `const ausgabe = document.querySelector('#ausgabe');` عنصر پیدا شده را نگه می‌دارد. اگر ID طور دیگری نوشته شده باشد، در ausgabe مقدار null است. نام را در HTML و JavaScript حرف به حرف بررسی کنید.","`const ausgabe = document.querySelector('#ausgabe');` speichert das gefundene Element. Ist die ID anders geschrieben, steht in ausgabe der Wert null.":"`const ausgabe = document.querySelector('#ausgabe');` عنصر پیدا شده را نگه می‌دارد. اگر ID طور دیگری نوشته شده باشد، در ausgabe مقدار null است.","textContent einsetzen":"به کار بردن textContent","textContent ersetzt den sichtbaren Text. Anders als innerHTML behandelt es Nutzereingaben nicht als HTML-Markup. Das hilft gegen unerwünschte Codeausführung. Ein Hinweisschild kann einen neuen Text bekommen, ohne dass du das ganze Schild austauschst. `ausgabe.textContent = 'Willkommen';` ersetzt den sichtbaren Inhalt. Auch Zeichen wie `<` werden dabei als Text behandelt. Das ist wichtig, wenn später fremde Eingaben angezeigt werden.":"textContent متن قابل دید را عوض می‌کند. برخلاف innerHTML، ورودی‌های کاربر را به عنوان HTML تفسیر نمی‌کند. این در برابر اجرای ناخواستهٔ کد کمک می‌کند. یک تابلوی راهنما می‌تواند متن تازه بگیرد، بدون اینکه تمام تابلو را عوض کنید. `ausgabe.textContent = 'Willkommen';` محتوای قابل دید را عوض می‌کند. حتی نشانه‌هایی مثل `<` هم به عنوان متن در نظر گرفته می‌شوند. این مهم است، وقتی بعداً ورودی‌های دیگران نشان داده شوند.","`ausgabe.textContent = 'Willkommen';` ersetzt den sichtbaren Inhalt. Auch Zeichen wie `<` werden dabei als Text behandelt.":"`ausgabe.textContent = 'Willkommen';` محتوای قابل دید را عوض می‌کند. حتی نشانه‌هایی مثل `<` هم به عنوان متن در نظر گرفته می‌شوند.","Auf Existenz prüfen":"بررسی وجود داشتن","Prüfe das Element vor dem Zugriff. Eine einfache if-Abfrage verhindert Fehler bei null. Platziere das Skript so, dass das HTML bereits geladen wurde. Ein Briefkasten muss montiert sein, bevor du einen Brief einwerfen kannst.":"پیش از دسترسی، عنصر را بررسی کنید. یک if ساده از خطا در null جلوگیری می‌کند. اسکریپت را طوری بگذارید که HTML از قبل بارگیری شده باشد. یک صندوق پست باید نصب شده باشد، پیش از اینکه بتوانید نامه‌ای در آن بیندازید.","`if (ausgabe)` prüft, ob das Element gefunden wurde. Erst im erfolgreichen Zweig änderst du textContent.":"`if (ausgabe)` بررسی می‌کند که آیا عنصر پیدا شد. فقط در شاخهٔ موفق textContent را تغییر می‌دهید.","ID im HTML stimmt nicht":"ID در HTML درست نیست","Falsch: `document.querySelector('#anzeige').textContent = 'Hallo';` kann `TypeError: Cannot set properties of null` auslösen, wenn das HTML nur `id='ausgabe'` enthält. Richtig: `document.querySelector('#ausgabe').textContent = 'Hallo';` trifft das vorhandene Element.":"اشتباه: `document.querySelector('#anzeige').textContent = 'Hallo';` می‌تواند `TypeError: Cannot set properties of null` ایجاد کند، اگر HTML فقط `id='ausgabe'` داشته باشد. درست: `document.querySelector('#ausgabe').textContent = 'Hallo';` به عنصر موجود می‌رسد.","innerHTML für fremde Texte benutzt":"innerHTML برای متن‌های بیگانه به کار رفت","Falsch: `ausgabe.innerHTML = eingabe;` kann eingegebenes HTML als echte Elemente darstellen, statt es als Text zu zeigen. Richtig: `ausgabe.textContent = eingabe;` zeigt auch `<b>Hallo</b>` wörtlich an.":"اشتباه: `ausgabe.innerHTML = eingabe;` ممکن است HTML واردشده را به عنوان عنصرهای واقعی نشان دهد، به جای اینکه آن را به شکل متن نشان دهد. درست: `ausgabe.textContent = eingabe;` حتی `<b>Hallo</b>` را کلمه به کلمه نشان می‌دهد.","Was findet #ausgabe?":"‎#ausgabe چه چیزی را پیدا می‌کند؟","Alle Links":"همهٔ لینک‌ها","Element mit passender ID":"عنصری با ID مناسب","Ein Stylesheet":"یک شیوه‌نامه (Stylesheet)","Hier passt „Element mit passender ID“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „عنصری با ID مناسب“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was setzt sicheren Text?":"چه چیزی متن مطمئن می‌گذارد؟","Hier passt „textContent“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „textContent“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was bedeutet null?":"null یعنی چه؟","Leerer Text":"متن خالی","Keine CSS-Regel":"هیچ قاعدهٔ CSS","Kein Element gefunden":"هیچ عنصری پیدا نشد","Hier passt „Kein Element gefunden“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „هیچ عنصری پیدا نشد“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Bei DOM ist die genaue JavaScript-Schreibweise wichtig.":"در DOM، املای دقیق JavaScript مهم است.","Nutze die Lösung `const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Willkommen';` als Vergleich für deine eigene Übung.":"از راه‌حل `const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Willkommen';` برای مقایسه با تمرین خودتان استفاده کنید.","Events":"رویدادها (Events)","Klicks mit addEventListener verarbeiten":"کلیک‌ها را با addEventListener پردازش کنید","Klick als Ereignis":"کلیک به عنوان رویداد","Ein Event ist ein Ereignis wie ein Klick. JavaScript kann darauf warten. So wird eine Seite interaktiv. Eine Türklingel löst erst beim Drücken ein Signal aus; ein Klick ist ähnlich. `addEventListener('click', ...)` wartet auf das Ereignis. Die Funktion wird nicht bereits beim Laden der Seite ausgeführt. So bleibt der Knopf für weitere Klicks bereit.":"یک Event رویدادی مثل یک کلیک است. JavaScript می‌تواند منتظر آن بماند. به این ترتیب یک صفحه تعاملی می‌شود. زنگ دروازه فقط با فشار دادن یک علامت می‌دهد؛ یک کلیک هم شبیه آن است. `addEventListener('click', ...)` منتظر رویداد می‌ماند. تابع همان هنگام بارگیری صفحه اجرا نمی‌شود. به این ترتیب دکمه برای کلیک‌های بعدی آماده می‌ماند.","`addEventListener('click', ...)` wartet auf das Ereignis. Die Funktion wird nicht bereits beim Laden der Seite ausgeführt.":"`addEventListener('click', ...)` منتظر رویداد می‌ماند. تابع همان هنگام بارگیری صفحه اجرا نمی‌شود.","Listener registrieren":"ثبت کردن Listener","addEventListener verbindet ein Element mit einer Funktion. Die Funktion wird erst beim Ereignis ausgeführt. Achte auf die Schreibweise click. Ein Empfangsdienst erhält eine Telefonnummer, nicht einen schon beendeten Anruf. `knopf.addEventListener('click', melden)` übergibt die Funktion selbst. Mit `melden()` würdest du sie bereits beim Registrieren aufrufen. Achte deshalb darauf, ob hinter dem Funktionsnamen Klammern stehen.":"addEventListener یک عنصر را با یک تابع وصل می‌کند. تابع فقط هنگام رویداد اجرا می‌شود. به املای click دقت کنید. یک دفتر پذیرش یک شمارهٔ تیلفون می‌گیرد، نه یک تماس که از قبل تمام شده است. `knopf.addEventListener('click', melden)` خود تابع را می‌دهد. با `melden()` آن را همان هنگام ثبت کردن صدا می‌زدید. به همین دلیل دقت کنید که آیا بعد از نام تابع قوس هست یا نه.","`knopf.addEventListener('click', melden)` übergibt die Funktion selbst. Mit `melden()` würdest du sie bereits beim Registrieren aufrufen.":"`knopf.addEventListener('click', melden)` خود تابع را می‌دهد. با `melden()` آن را همان هنگام ثبت کردن صدا می‌زدید.","Rückmeldung zeigen":"نشان دادن پاسخ","Im Listener kannst du Text ändern. Eine Meldung wie Gespeichert bestätigt die Aktion. Das ist für Nutzerinnen und Nutzer eine wichtige Rückmeldung. Eine Quittung bestätigt eine Zahlung; ein Statussatz bestätigt einen Klick. `ausgabe.textContent = 'Gespeichert';` aktualisiert die Meldung. Die Änderung erfolgt innerhalb der Klick-Funktion. Klicke zweimal und kontrolliere, dass die Meldung verständlich bleibt.":"در Listener می‌توانید متن را تغییر دهید. پیامی مثل Gespeichert کار را تأیید می‌کند. این یک پاسخ مهم برای کاربران است. یک رسید یک پرداخت را تأیید می‌کند؛ یک جملهٔ وضعیت یک کلیک را تأیید می‌کند. `ausgabe.textContent = 'Gespeichert';` پیام را به‌روز می‌کند. این تغییر داخل تابع کلیک انجام می‌شود. دو بار کلیک کنید و بررسی کنید که پیام قابل فهم بماند.","`ausgabe.textContent = 'Gespeichert';` aktualisiert die Meldung. Die Änderung erfolgt innerhalb der Klick-Funktion.":"`ausgabe.textContent = 'Gespeichert';` پیام را به‌روز می‌کند. این تغییر داخل تابع کلیک انجام می‌شود.","Tastatur prüfen":"بررسی کیبورد","Ein echtes button-Element funktioniert auch mit der Tastatur. Teste Tab und Enter. Ein klickbarer Absatz ist dafür keine gleichwertige Lösung. Eine barrierefreie Tür lässt sich auf mehreren Wegen öffnen.":"یک عنصر button واقعی با کیبورد هم کار می‌کند. Tab و Enter را آزمایش کنید. یک پاراگراف قابل کلیک برای این کار راه‌حل برابر نیست. یک دروازهٔ دسترس‌پذیر از چند راه باز می‌شود.","Ein HTML-button reagiert neben der Maus auch auf Tastatureingaben. Erreiche den Knopf mit Tab und aktiviere ihn mit Enter.":"یک button در HTML علاوه بر موس به ورودی‌های کیبورد هم واکنش نشان می‌دهد. با Tab به دکمه برسید و با Enter آن را فعال کنید.","Funktion sofort statt beim Klick ausgeführt":"تابع فوراً به جای هنگام کلیک اجرا شد","Falsch: `knopf.addEventListener('click', melden());` ruft melden sofort auf; beim Klick passiert danach nichts oder ein TypeError entsteht. Richtig: `knopf.addEventListener('click', melden);` übergibt die Funktion ohne Klammern.":"اشتباه: `knopf.addEventListener('click', melden());` ‏melden را فوراً صدا می‌زند؛ هنگام کلیک بعد از آن یا هیچ اتفاقی نمی‌افتد یا یک TypeError پیدا می‌شود. درست: `knopf.addEventListener('click', melden);` تابع را بدون قوس می‌دهد.","Listener an null registriert":"Listener روی null ثبت شد","Falsch: `document.querySelector('#knop').addEventListener('click', melden);` löst `TypeError: Cannot read properties of null` aus, wenn der Knopf `id='knopf'` heißt. Richtig: `document.querySelector('#knopf').addEventListener('click', melden);`.":"اشتباه: `document.querySelector('#knop').addEventListener('click', melden);` خطای `TypeError: Cannot read properties of null` می‌دهد، اگر نام دکمه `id='knopf'` باشد. درست: `document.querySelector('#knopf').addEventListener('click', melden);`.","Wie heißt das Klick-Ereignis?":"رویداد کلیک چه نام دارد؟","Hier passt „click“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „click“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was registriert einen Listener?":"چه چیزی یک Listener را ثبت می‌کند؟","Hier passt „addEventListener“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „addEventListener“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Warum button verwenden?":"چرا button را به کار ببریم؟","Es lädt schneller":"سریع‌تر بارگیری می‌شود","Es braucht kein CSS":"به CSS نیاز ندارد","Es ist per Tastatur bedienbar":"با کیبورد قابل استفاده است","Hier passt „Es ist per Tastatur bedienbar“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „با کیبورد قابل استفاده است“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Bei Events ist die genaue JavaScript-Schreibweise wichtig.":"در رویدادها، املای دقیق JavaScript مهم است.","Nutze die Lösung `const knopf = document.querySelector('#knopf'); const ausgabe = document.querySelector('#ausgabe'); if (knopf && ausgabe) knopf.addEventListener('click', () => { ausgabe.textContent = 'Gespeichert'; });` als Vergleich für deine eigene Übung.":"از راه‌حل `const knopf = document.querySelector('#knopf'); const ausgabe = document.querySelector('#ausgabe'); if (knopf && ausgabe) knopf.addEventListener('click', () => { ausgabe.textContent = 'Gespeichert'; });` برای مقایسه با تمرین خودتان استفاده کنید.","Konsole":"کنسول","JavaScript-Fehler systematisch untersuchen":"خطاهای JavaScript را منظم بررسی کنید","Werte protokollieren":"ثبت کردن مقدارها","console.log zeigt Werte in der Entwicklerkonsole. Damit erkennst du Zwischenergebnisse. Beschrifte deine Ausgaben verständlich. Ein Techniker liest die Anzeige eines Geräts, bevor er etwas austauscht. `console.log('Gefunden:', Boolean(element));` zeigt einen beschrifteten Wert. Boolean wandelt die Existenz des Elements in true oder false um. So erkennst du, ob die Suche überhaupt erfolgreich war.":"console.log مقدارها را در کنسول توسعه‌دهنده نشان می‌دهد. با آن نتیجه‌های میانی را می‌شناسید. خروجی‌های خود را قابل فهم برچسب بزنید. یک تکنیشن پیش از عوض کردن چیزی نمایش یک دستگاه را می‌خواند. `console.log('Gefunden:', Boolean(element));` یک مقدار برچسب‌دار نشان می‌دهد. Boolean وجود داشتن عنصر را به true یا false تبدیل می‌کند. به این ترتیب می‌فهمید که آیا جستجو اصلاً موفق بود.","`console.log('Gefunden:', Boolean(element));` zeigt einen beschrifteten Wert. Boolean wandelt die Existenz des Elements in true oder false um.":"`console.log('Gefunden:', Boolean(element));` یک مقدار برچسب‌دار نشان می‌دهد. Boolean وجود داشتن عنصر را به true یا false تبدیل می‌کند.","SyntaxError erkennen":"شناختن SyntaxError","Ein SyntaxError weist auf ungültige Schreibweise hin. Prüfe Klammern und Anführungszeichen. Die Zeilennummer hilft beim Suchen. Ein falsch geschriebenes Wort auf einem Formular verhindert das Verständnis. `console.log('Hallo'` fehlt die schließende runde Klammer. Der Browser meldet einen SyntaxError und führt den Code nicht aus. Ergänze `);` und starte die Prüfung erneut.":"یک SyntaxError به املای نامعتبر اشاره می‌کند. قوس‌ها و علامه‌های نقل‌قول را بررسی کنید. شمارهٔ خط در جستجو کمک می‌کند. یک کلمهٔ اشتباه نوشته‌شده در یک فورم مانع فهمیدن می‌شود. در `console.log('Hallo'` قوس گرد بسته کم است. براوزر یک SyntaxError می‌دهد و کد را اجرا نمی‌کند. `);` را اضافه کنید و بررسی را دوباره شروع کنید.","`console.log('Hallo'` fehlt die schließende runde Klammer. Der Browser meldet einen SyntaxError und führt den Code nicht aus.":"در `console.log('Hallo'` قوس گرد بسته کم است. براوزر یک SyntaxError می‌دهد و کد را اجرا نمی‌کند.","TypeError verstehen":"فهمیدن TypeError","Ein TypeError kann bei einem Zugriff auf null entstehen. Kontrolliere das Ergebnis von querySelector. Eine if-Abfrage schützt vor dem Zugriff. Eine Lieferung an eine unbekannte Adresse kann nicht ankommen. `document.querySelector('#fehlt')` liefert null, wenn es kein Ziel gibt. Ein direkter Zugriff auf `.textContent` erzeugt dann einen TypeError. Mit `if (element)` vermeidest du diesen Zugriff.":"یک TypeError ممکن است هنگام دسترسی به null پیدا شود. نتیجهٔ querySelector را بررسی کنید. یک if از دسترسی محافظت می‌کند. یک تحویل به یک آدرس ناشناخته نمی‌تواند برسد. `document.querySelector('#fehlt')` وقتی هدفی نباشد null می‌دهد. در آن صورت دسترسی مستقیم به `.textContent` یک TypeError ایجاد می‌کند. با `if (element)` از این دسترسی جلوگیری می‌کنید.","`document.querySelector('#fehlt')` liefert null, wenn es kein Ziel gibt. Ein direkter Zugriff auf `.textContent` erzeugt dann einen TypeError.":"`document.querySelector('#fehlt')` وقتی هدفی نباشد null می‌دهد. در آن صورت دسترسی مستقیم به `.textContent` یک TypeError ایجاد می‌کند.","Gezielt erneut testen":"آزمایش دوبارهٔ هدفمند","Ändere jeweils nur eine Stelle. Starte danach den Test erneut. Entferne überflüssige Debug-Ausgaben vor der Veröffentlichung. Beim Reparieren eines Fahrrads prüfst du nach jeder Änderung nur das betroffene Teil. Setze eine beschriftete console.log-Ausgabe vor den verdächtigen Abschnitt. Beobachte den Wert und ändere danach genau eine Anweisung. Wiederhole den Test, bis die Fehlermeldung verschwindet.":"هر بار فقط یک جا را تغییر دهید. بعد از آن آزمایش را دوباره شروع کنید. خروجی‌های اضافی Debug را پیش از نشر پاک کنید. هنگام ترمیم یک بایسکل بعد از هر تغییر فقط همان بخش مربوط را بررسی می‌کنید. یک خروجی console.log برچسب‌دار را پیش از بخش مشکوک بگذارید. مقدار را ببینید و بعد دقیقاً یک دستور را تغییر دهید. آزمایش را تکرار کنید تا پیام خطا ناپدید شود.","Setze eine beschriftete console.log-Ausgabe vor den verdächtigen Abschnitt. Beobachte den Wert und ändere danach genau eine Anweisung.":"یک خروجی console.log برچسب‌دار را پیش از بخش مشکوک بگذارید. مقدار را ببینید و بعد دقیقاً یک دستور را تغییر دهید.","Syntaxfehler überlesen":"نادیده گرفتن خطای نحوی","Falsch: `console.log('Hallo'` erzeugt `SyntaxError: missing ) after argument list` oder eine entsprechende Syntaxmeldung. Die schließende Klammer fehlt. Richtig: `console.log('Hallo');` lässt sich ausführen.":"اشتباه: `console.log('Hallo'` خطای `SyntaxError: missing ) after argument list` یا یک پیام نحوی مشابه ایجاد می‌کند. قوس بسته کم است. درست: `console.log('Hallo');` اجرا می‌شود.","Auf null ohne Prüfung zugegriffen":"دسترسی به null بدون بررسی","Falsch: `document.querySelector('#fehlt').textContent = 'OK';` löst `TypeError: Cannot set properties of null` aus, wenn es das Element nicht gibt. Richtig: `const el = document.querySelector('#fehlt'); if (el) el.textContent = 'OK';`.":"اشتباه: `document.querySelector('#fehlt').textContent = 'OK';` خطای `TypeError: Cannot set properties of null` می‌دهد، اگر آن عنصر وجود نداشته باشد. درست: `const el = document.querySelector('#fehlt'); if (el) el.textContent = 'OK';`.","Was zeigt console.log?":"console.log چه نشان می‌دهد؟","Nur Bilder":"فقط عکس‌ها","Werte in der Konsole":"مقدارها در کنسول","Nur HTML":"فقط HTML","Hier passt „Werte in der Konsole“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „مقدارها در کنسول“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was ist SyntaxError?":"SyntaxError چیست؟","Ungültige Schreibweise":"املای نامعتبر","Fehlendes Internet":"انترنت قطع","Falsche Farbe":"رنگ اشتباه","Hier passt „Ungültige Schreibweise“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „املای نامعتبر“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was vor textContent prüfen?":"پیش از textContent چه چیزی را بررسی کنیم؟","Schriftgröße":"اندازهٔ فونت","Fensterhöhe":"ارتفاع پنجره","Element ist nicht null":"عنصر null نیست","Hier passt „Element ist nicht null“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „عنصر null نیست“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Bei Konsole ist die genaue JavaScript-Schreibweise wichtig.":"در کنسول، املای دقیق JavaScript مهم است.","Nutze die Lösung `const element = document.querySelector('#ausgabe'); console.log('Gefunden:', Boolean(element));` als Vergleich für deine eigene Übung.":"از راه‌حل `const element = document.querySelector('#ausgabe'); console.log('Gefunden:', Boolean(element));` برای مقایسه با تمرین خودتان استفاده کنید.","Projekt: To-do-Liste":"پروژه: لست کارها","Eine kleine Aufgabenliste mit Eingabe und Knopf bauen":"یک لست کوچک کارها با ورودی و دکمه بسازید","Eingabe beschriften":"برچسب زدن به ورودی","Eine Aufgabenliste braucht ein Eingabefeld. Verbinde label und input über for und id. Der Knopf startet das Hinzufügen. Ein Notizblock braucht eine Zeile für jede neue Aufgabe.":"یک لست کارها به یک خانهٔ ورودی نیاز دارد. label و input را از راه for و id وصل کنید. دکمه اضافه کردن را شروع می‌کند. یک کتابچهٔ یادداشت برای هر کار تازه یک خط لازم دارد.","`<label for='aufgabe'>` beschreibt das Eingabefeld. Das zugehörige input hat die ID aufgabe.":"`<label for='aufgabe'>` خانهٔ ورودی را توصیف می‌کند. input مربوط ID ‏aufgabe را دارد.","Leere Aufgaben vermeiden":"جلوگیری از کارهای خالی","Mit value liest du die Eingabe. trim entfernt Leerzeichen am Anfang und Ende. Eine leere Eingabe darf keinen Eintrag erzeugen. Auf einem Einkaufszettel hilft eine leere Zeile niemandem. `feld.value.trim()` entfernt Leerzeichen am Rand. `if (!text) return;` beendet den Klickablauf bei leerem Text. Teste Eingaben mit nur drei Leerzeichen und mit einem echten Wort.":"با value ورودی را می‌خوانید. trim فاصله‌های شروع و پایان را پاک می‌کند. یک ورودی خالی نباید عنصری بسازد. در یک لست خرید یک خط خالی به کسی کمک نمی‌کند. `feld.value.trim()` فاصله‌های دو طرف را پاک می‌کند. `if (!text) return;` روند کلیک را در متن خالی تمام می‌کند. ورودی‌ها را با فقط سه فاصله و با یک کلمهٔ واقعی آزمایش کنید.","`feld.value.trim()` entfernt Leerzeichen am Rand. `if (!text) return;` beendet den Klickablauf bei leerem Text.":"`feld.value.trim()` فاصله‌های دو طرف را پاک می‌کند. `if (!text) return;` روند کلیک را در متن خالی تمام می‌کند.","Listeneinträge erzeugen":"ساختن عنصرهای لست","createElement erzeugt ein neues li-Element. Mit textContent setzt du den Aufgabentext sicher. appendChild fügt den Eintrag in die Liste ein. Eine neue Karteikarte wird erst erstellt und danach beschriftet. `document.createElement('li')` erzeugt einen Listeneintrag. `li.textContent = text` schreibt die Aufgabe sicher hinein. `liste.appendChild(li)` hängt den Eintrag an die sichtbare Liste.":"createElement یک عنصر li تازه می‌سازد. با textContent متن کار را مطمئن می‌گذارید. appendChild عنصر را به لست اضافه می‌کند. یک کارت یادداشت تازه اول ساخته و بعد نوشته می‌شود. `document.createElement('li')` یک عنصر لست می‌سازد. `li.textContent = text` کار را مطمئن داخل آن می‌نویسد. `liste.appendChild(li)` عنصر را به لست قابل دید اضافه می‌کند.","`document.createElement('li')` erzeugt einen Listeneintrag. `li.textContent = text` schreibt die Aufgabe sicher hinein.":"`document.createElement('li')` یک عنصر لست می‌سازد. `li.textContent = text` کار را مطمئن داخل آن می‌نویسد.","Aufgaben nach Klick anzeigen":"نشان دادن کارها بعد از کلیک","Leere das Feld nach dem Hinzufügen. Probiere mehrere Aufgaben nacheinander. Kontrolliere die Bedienung auch auf einem kleinen Handy. Nach dem Eintragen einer Aufgabe ist der Stift wieder frei für die nächste. `feld.value = ''` leert das Eingabefeld nach dem Hinzufügen. Ein erneuter Klick mit leerem Feld darf keinen Eintrag erzeugen. Teste zwei unterschiedliche Aufgaben nacheinander.":"بعد از اضافه کردن خانه را خالی کنید. چند کار را پشت سر هم امتحان کنید. کار کردن را در یک موبایل کوچک هم بررسی کنید. بعد از نوشتن یک کار، قلم دوباره برای کار بعدی آزاد است. `feld.value = ''` خانهٔ ورودی را بعد از اضافه کردن خالی می‌کند. یک کلیک دوباره با خانهٔ خالی نباید عنصری بسازد. دو کار مختلف را پشت سر هم آزمایش کنید.","`feld.value = ''` leert das Eingabefeld nach dem Hinzufügen. Ein erneuter Klick mit leerem Feld darf keinen Eintrag erzeugen.":"`feld.value = ''` خانهٔ ورودی را بعد از اضافه کردن خالی می‌کند. یک کلیک دوباره با خانهٔ خالی نباید عنصری بسازد.","Leere Aufgaben gespeichert":"کارهای خالی ذخیره شدند","Falsch: `aufgaben.push(feld.value);` übernimmt auch `   ` als Aufgabe; in der Vorschau erscheint ein leerer Listeneintrag. Richtig: `const text = feld.value.trim(); if (!text) return; aufgaben.push(text);`.":"اشتباه: `aufgaben.push(feld.value);` حتی `   ` را هم به عنوان کار می‌پذیرد؛ در پیش‌نمایش یک عنصر خالی لست دیده می‌شود. درست: `const text = feld.value.trim(); if (!text) return; aufgaben.push(text);`.","Eingabetext mit innerHTML eingesetzt":"متن ورودی با innerHTML گذاشته شد","Falsch: `liste.innerHTML += '<li>' + feld.value + '</li>';` interpretiert eingegebenes HTML und kann unerwünschte Elemente erzeugen. Richtig: `const li = document.createElement('li'); li.textContent = feld.value; liste.appendChild(li);`.":"اشتباه: `liste.innerHTML += '<li>' + feld.value + '</li>';` ‏HTML واردشده را تفسیر می‌کند و ممکن است عنصرهای ناخواسته بسازد. درست: `const li = document.createElement('li'); li.textContent = feld.value; liste.appendChild(li);`.","Was entfernt trim?":"trim چه چیزی را پاک می‌کند؟","Rand-Leerzeichen":"فاصله‌های دو طرف","Alle Zahlen":"همهٔ عددها","Alle Einträge":"همهٔ عنصرها","Hier passt „Rand-Leerzeichen“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „فاصله‌های دو طرف“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Wie erzeugst du li?":"li را چطور می‌سازید؟","Hier passt „createElement“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „createElement“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Wie zeigst du Text sicher?":"متن را چطور مطمئن نشان می‌دهید؟","Bei Projekt: To-do-Liste ist die genaue JavaScript-Schreibweise wichtig.":"در پروژهٔ لست کارها، املای دقیق JavaScript مهم است.","Nutze die Lösung `const feld = document.querySelector('#aufgabe'); const liste = document.querySelector('#liste'); document.querySelector('#hinzufuegen').addEventListener('click', () => { const text = feld.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = text; liste.appendChild(li); feld.value = ''; });` als Vergleich für deine eigene Übung.":"از راه‌حل `const feld = document.querySelector('#aufgabe'); const liste = document.querySelector('#liste'); document.querySelector('#hinzufuegen').addEventListener('click', () => { const text = feld.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = text; liste.appendChild(li); feld.value = ''; });` برای مقایسه با تمرین خودتان استفاده کنید.","JavaScript kennt nur einen Zahltyp, `number`, für ganze Zahlen und Kommazahlen gemeinsam. Intern sind es 64-Bit-Gleitkommazahlen, deshalb ergibt `0.1 + 0.2` auch hier `0.30000000000000004`. Für sehr große ganze Zahlen gibt es zusätzlich den Typ `bigint`, erkennbar am `n` hinter der Zahl.":"JavaScript فقط یک نوع عدد می‌شناسد، `number`، برای اعداد صحیح و اعشاری با هم. در داخل، این‌ها اعداد ممیز شناور 64 بیتی هستند، به همین دلیل `0.1 + 0.2` اینجا هم `0.30000000000000004` می‌شود. برای اعداد صحیح خیلی بزرگ علاوه بر آن نوع `bigint` هست که از `n` بعد از عدد شناخته می‌شود.","`const` legt eine Variable an, die nicht neu zugewiesen werden kann; `let` erlaubt eine spätere Änderung. Das ältere `var` solltest du nicht mehr verwenden, weil es sich bei Gültigkeitsbereichen überraschend verhält. Gute Regel: Nimm `const`, solange du nicht weißt, dass sich der Wert ändern muss.":"`const` متغیری می‌سازد که نمی‌توان دوباره به آن مقدار داد؛ `let` تغییر بعدی را اجازه می‌دهد. `var` قدیمی‌تر را دیگر به کار نبرید، چون در محدوده‌های اعتبار رفتار غافلگیرکننده‌ای دارد. قاعدهٔ خوب: `const` را بگیرید، تا وقتی که نمی‌دانید مقدار باید تغییر کند.","Strings dürfen in einfachen `'...'` oder doppelten `\"...\"` Anführungszeichen stehen. Mit Backticks entstehen Template-Strings, in die man Werte mit `${...}` einsetzt – ähnlich wie f-Strings in Python. Template-Strings dürfen außerdem über mehrere Zeilen gehen.":"رشته‌ها می‌توانند در نقل‌قول تکی `'...'` یا دوتایی `\"...\"` باشند. با Backtick رشته‌های قالب ساخته می‌شوند که مقدارها با `${...}` در آن‌ها گذاشته می‌شوند – شبیه f-String ها در پایتون. رشته‌های قالب علاوه بر آن می‌توانند چند خط باشند.","Vorsicht beim Pluszeichen: Ist einer der Werte ein String, verbindet JavaScript statt zu rechnen. `'5' + 3` ergibt `'53'`, `'5' - 3` dagegen `2`, weil Minus nur für Zahlen definiert ist. Mit `Number('5')` wandelst du einen Text ausdrücklich in eine Zahl um.":"در علامت جمع احتیاط کنید: اگر یکی از مقدارها رشته باشد، JavaScript به جای حساب کردن به هم وصل می‌کند. `'5' + 3` می‌شود `'53'`، اما `'5' - 3` می‌شود `2`، چون منها فقط برای عددها تعریف شده است. با `Number('5')` یک متن را صریح به عدد تبدیل می‌کنید.","Booleans entstehen meist aus Vergleichen. Verwende in JavaScript immer `===` und `!==`: Sie prüfen Wert und Typ. Das ältere `==` wandelt vorher Typen um, sodass `'0' == 0` wahr ist – eine bekannte Fehlerquelle.":"Boolean ها بیشتر از مقایسه‌ها ساخته می‌شوند. در JavaScript همیشه `===` و `!==` را به کار ببرید: مقدار و نوع را بررسی می‌کنند. `==` قدیمی‌تر پیش از آن نوع‌ها را تبدیل می‌کند، طوری که `'0' == 0` درست است – یک منبع خطای شناخته‌شده.","In Bedingungen behandelt JavaScript bestimmte Werte als „falsy“: `false`, `0`, `''` (leerer Text), `null`, `undefined` und `NaN`. Alle anderen Werte gelten als „truthy“, sogar `'0'` und ein leeres Array `[]`. Wer diese Regel kennt, versteht viele überraschende Ergebnisse.":"در شرط‌ها JavaScript مقدارهای مشخصی را «falsy» حساب می‌کند: `false`، `0`، `''` (متن خالی)، `null`، `undefined` و `NaN`. همهٔ مقدارهای دیگر «truthy» حساب می‌شوند، حتی `'0'` و یک آرایهٔ خالی `[]`. کسی که این قاعده را بشناسد، بسیاری از نتیجه‌های غافلگیرکننده را می‌فهمد.","Neben `number`, `string` und `boolean` gibt es die Grundtypen `undefined` (kein Wert zugewiesen), `null` (bewusst leer), `bigint` und `symbol`. Alles andere – Arrays, Funktionen, Objekte – ist ein Objekt. Ein bekannter historischer Fehler: `typeof null` liefert `'object'`.":"کنار `number`، `string` و `boolean` نوع‌های پایهٔ `undefined` (مقداری داده نشده)، `null` (عمداً خالی)، `bigint` و `symbol` هستند. هر چیز دیگر – آرایه‌ها، تابع‌ها، شیءها – یک شیء است. یک خطای تاریخی شناخته‌شده: `typeof null` نتیجهٔ `'object'` می‌دهد.","Für Arrays liefert `typeof` ebenfalls `'object'`. Ob etwas ein Array ist, prüfst du mit `Array.isArray(wert)`. JavaScript ist dynamisch typisiert: Eine mit `let` angelegte Variable kann später einen Wert anderen Typs bekommen. TypeScript ergänzt Typprüfungen wie in C++ und Rust.":"برای آرایه‌ها هم `typeof` نتیجهٔ `'object'` می‌دهد. اینکه چیزی آرایه است را با `Array.isArray(wert)` بررسی می‌کنید. JavaScript نوع‌دهی پویا دارد: متغیری که با `let` ساخته شده می‌تواند بعداً مقداری از نوع دیگر بگیرد. TypeScript بررسی نوع را مثل C++ و Rust اضافه می‌کند.","Arrays dürfen Werte verschiedener Typen mischen und sogar weitere Arrays enthalten. Auch mit `const` angelegt, bleibt das Array veränderbar: `const` verhindert nur, dass die Variable auf ein anderes Array zeigt, nicht dass sich der Inhalt ändert.":"آرایه‌ها می‌توانند مقدارهایی از نوع‌های مختلف را مخلوط کنند و حتی آرایه‌های دیگر داشته باشند. حتی اگر با `const` ساخته شود، آرایه قابل تغییر می‌ماند: `const` فقط جلوی اشاره کردن متغیر به آرایهٔ دیگری را می‌گیرد، نه تغییر محتوا را.","Arrays sind in JavaScript Objekte, und Variablen speichern einen Verweis darauf. Bei `const b = a;` zeigen beide Namen auf dasselbe Array – eine Änderung über `b` sieht man auch über `a`. Eine echte Kopie erstellst du mit `[...a]`.":"آرایه‌ها در JavaScript شیء هستند و متغیرها یک ارجاع به آن‌ها ذخیره می‌کنند. در `const b = a;` هر دو نام به همان آرایه اشاره می‌کنند – تغییری از راه `b` از راه `a` هم دیده می‌شود. یک کپی واقعی را با `[...a]` می‌سازید.","Ein Zugriff auf eine Position, die es nicht gibt, liefert in JavaScript keinen Fehler, sondern `undefined`. Das ist bequem, kann aber Fehler verschleiern. Den letzten Eintrag erreichst du mit `einkauf.at(-1)` oder `einkauf[einkauf.length - 1]`.":"دسترسی به جایگاهی که وجود ندارد در JavaScript خطا نمی‌دهد، بلکه `undefined`. این راحت است، اما ممکن است خطاها را پنهان کند. آخرین عنصر را با `einkauf.at(-1)` یا `einkauf[einkauf.length - 1]` می‌گیرید.","Mit `einkauf.indexOf('Milch')` findest du die Position eines Werts; fehlt er, ergibt sich `-1`. `einkauf.includes('Milch')` antwortet einfach mit `true` oder `false`. Beide vergleichen mit `===`.":"با `einkauf.indexOf('Milch')` جایگاه یک مقدار را پیدا می‌کنید؛ اگر نباشد، `-1` به دست می‌آید. `einkauf.includes('Milch')` ساده با `true` یا `false` جواب می‌دهد. هر دو با `===` مقایسه می‌کنند.","`push` verändert das Array direkt und gibt die neue Länge zurück. Weitere wichtige Methoden: `pop` entfernt den letzten Eintrag, `unshift` und `shift` arbeiten am Anfang, `splice` fügt an beliebiger Stelle ein oder entfernt. Methoden, die das Original verändern, nennt man mutierend.":"`push` آرایه را مستقیم تغییر می‌دهد و طول تازه را برمی‌گرداند. متدهای مهم دیگر: `pop` آخرین عنصر را حذف می‌کند، `unshift` و `shift` در اول کار می‌کنند و `splice` در هر جایی اضافه یا حذف می‌کند. متدهایی را که اصل را تغییر می‌دهند تغییردهنده (mutating) می‌نامند.","In modernen Webanwendungen, etwa mit React, erstellt man oft lieber ein neues Array, statt das alte zu verändern: `const neu = [...einkauf, 'Reis'];`. So lässt sich leichter erkennen, ob sich Daten geändert haben. Beide Stile haben ihren Platz.":"در برنامه‌های وب امروزی، مثلاً با React، اغلب ترجیح می‌دهند یک آرایهٔ تازه بسازند تا اینکه قدیمی را تغییر دهند: `const neu = [...einkauf, 'Reis'];`. به این ترتیب آسان‌تر می‌توان فهمید داده‌ها تغییر کرده‌اند یا نه. هر دو سبک جای خود را دارند.","`length` ist immer um eins größer als der höchste Index, weil die Zählung bei null beginnt. Ein Array mit drei Einträgen hat die Indizes 0, 1 und 2. Darum lautet die Bedingung in Zählschleifen `i < liste.length` und nicht `<=`.":"`length` همیشه یکی بیشتر از بالاترین اندیس است، چون شمردن از صفر شروع می‌شود. یک آرایه با سه عنصر اندیس‌های 0، 1 و 2 دارد. به همین دلیل شرط در حلقه‌های شمارشی `i < liste.length` است و نه `<=`.","Man kann `length` sogar setzen: `einkauf.length = 0` leert das Array vollständig. Das wirkt auf alle Variablen, die auf dasselbe Array verweisen. Für Neulinge ist `einkauf = []` mit `let` oft verständlicher, erzeugt aber ein neues Array.":"حتی می‌توان `length` را مقدار داد: `einkauf.length = 0` آرایه را کاملاً خالی می‌کند. این روی همهٔ متغیرهایی که به همان آرایه اشاره می‌کنند اثر دارد. برای تازه‌کارها `einkauf = []` با `let` اغلب قابل فهم‌تر است، اما یک آرایهٔ تازه می‌سازد.","Schleifen setzen das DRY-Prinzip um: Don't Repeat Yourself. Statt dieselbe Zeile zehnmal zu schreiben, beschreibst du einmal, was für jedes Element passieren soll. Ändert sich die Liste, passt sich die Schleife automatisch an.":"حلقه‌ها اصل DRY را پیاده می‌کنند: Don't Repeat Yourself. به جای اینکه همان خط را ده بار بنویسید، یک بار توصیف می‌کنید برای هر عنصر چه باید بشود. اگر لیست تغییر کند، حلقه خودکار خودش را تطبیق می‌دهد.","JavaScript kennt mehrere Schleifenarten: `for`, `for...of`, `while`, `do...while` und `for...in`. Hinzu kommen Array-Methoden wie `forEach`, `map` und `filter`, die in modernem Code sehr häufig sind und eine Schleife oft ersetzen.":"JavaScript چند نوع حلقه می‌شناسد: `for`، `for...of`، `while`، `do...while` و `for...in`. علاوه بر آن متدهای آرایه مثل `forEach`، `map` و `filter` هستند که در کد امروزی بسیار رایج‌اند و اغلب جای یک حلقه را می‌گیرند.","`for...of` funktioniert mit allem, was iterierbar ist: Arrays, Strings (Zeichen für Zeichen), Maps und Sets. Willst du zusätzlich die Position wissen, schreibe `for (const [i, name] of namen.entries())`.":"`for...of` با هر چیزی که قابل پیمایش است کار می‌کند: آرایه‌ها، رشته‌ها (نویسه به نویسه)، Map ها و Set ها. اگر بخواهید جایگاه را هم بدانید، `for (const [i, name] of namen.entries())` بنویسید.","Verwechsle es nicht mit `for...in`: Das liefert die Schlüssel eines Objekts, bei Arrays also die Indizes als Texte. Für Arrays ist `for...of` die richtige Wahl, für die Eigenschaften eines Objekts `Object.entries(obj)`.":"آن را با `for...in` اشتباه نکنید: آن کلیدهای یک شیء را می‌دهد، در آرایه‌ها یعنی اندیس‌ها را به شکل متن. برای آرایه‌ها `for...of` انتخاب درست است و برای ویژگی‌های یک شیء `Object.entries(obj)`.","Die klassische Schleife hat drei Teile, getrennt durch Semikolons: Start (`let i = 0`), Bedingung (`i < 3`) und Schritt (`i++`). Die Bedingung wird vor jedem Durchlauf geprüft. Der Schritt läuft nach jedem Durchlauf.":"حلقهٔ کلاسیک سه بخش دارد که با نقطه‌ویرگول جدا می‌شوند: شروع (`let i = 0`)، شرط (`i < 3`) و گام (`i++`). شرط پیش از هر دور بررسی می‌شود. گام بعد از هر دور اجرا می‌شود.","Hier muss `let` stehen, nicht `const`, weil sich `i` ändert. Jeder Durchlauf bekommt in JavaScript eine eigene Kopie von `i`. Das ist wichtig, wenn innerhalb der Schleife Funktionen erzeugt werden, die später aufgerufen werden.":"اینجا باید `let` باشد، نه `const`، چون `i` تغییر می‌کند. در JavaScript هر دور یک کپی جداگانه از `i` می‌گیرد. این مهم است وقتی داخل حلقه تابع‌هایی ساخته می‌شوند که بعداً صدا زده می‌شوند.","Eine Endlosschleife blockiert im Browser die gesamte Seite: Weil JavaScript im Browser auf einem einzigen Haupt-Thread läuft, reagieren dann weder Knöpfe noch Scrollen. Nach einiger Zeit bietet der Browser an, das Skript abzubrechen.":"یک حلقهٔ بی‌پایان در مرورگر کل صفحه را قفل می‌کند: چون JavaScript در مرورگر روی یک رشتهٔ اصلی تنها اجرا می‌شود، آن وقت نه دکمه‌ها واکنش نشان می‌دهند و نه اسکرول. بعد از مدتی مرورگر پیشنهاد می‌کند اسکریپت را قطع کند.","Für Daten, die nach und nach eintreffen, nutzt man im Browser keine Warteschleifen, sondern Ereignisse und Zeitgeber wie `setTimeout`. Mit `break` verlässt du eine Schleife vorzeitig, mit `continue` springst du zum nächsten Durchlauf.":"برای داده‌هایی که کم‌کم می‌رسند، در مرورگر از حلقه‌های انتظار استفاده نمی‌کنند، بلکه از رویدادها و زمان‌سنج‌هایی مثل `setTimeout`. با `break` یک حلقه را زودتر ترک می‌کنید و با `continue` به دور بعدی می‌پرید.","Funktionsnamen beginnen üblicherweise mit einem Verb und werden in camelCase geschrieben, etwa `berechneSumme` oder `zeigeMeldung`. Eine mit `function` deklarierte Funktion kann man schon vor ihrer Definition im Code aufrufen; dieses Verhalten heißt Hoisting.":"نام تابع‌ها معمولاً با یک فعل شروع می‌شوند و به شکل camelCase نوشته می‌شوند، مثلاً `berechneSumme` یا `zeigeMeldung`. تابعی که با `function` اعلان شده را می‌توان حتی پیش از تعریفش در کد صدا زد؛ این رفتار Hoisting نام دارد.","Daneben gibt es Pfeilfunktionen: `const doppelt = (zahl) => zahl * 2;`. Steht rechts vom Pfeil nur ein Ausdruck, wird er automatisch zurückgegeben. Pfeilfunktionen sind besonders bei kurzen Rückruffunktionen beliebt, etwa für Ereignisse.":"کنار آن تابع‌های پیکانی هستند: `const doppelt = (zahl) => zahl * 2;`. اگر سمت راست پیکان فقط یک عبارت باشد، خودکار برگردانده می‌شود. تابع‌های پیکانی به‌خصوص برای تابع‌های بازگشتی کوتاه محبوب‌اند، مثلاً برای رویدادها.","Fehlt beim Aufruf ein Argument, ist der Parameter `undefined` – JavaScript meldet keinen Fehler. Mit einem Standardwert vermeidest du das: `function gruss(name = 'Gast')`. Überzählige Argumente werden ignoriert.":"اگر در صدا زدن یک آرگومان کم باشد، پارامتر `undefined` است – JavaScript خطایی نمی‌دهد. با یک مقدار پیش‌فرض از این جلوگیری می‌کنید: `function gruss(name = 'Gast')`. آرگومان‌های اضافی نادیده گرفته می‌شوند.","Primitive Werte wie Zahlen und Texte werden als Kopie übergeben. Bei Objekten und Arrays erhält die Funktion einen Verweis: Verändert sie das Objekt, ist die Änderung auch außerhalb sichtbar. Darum sollte eine Funktion übergebene Objekte nur verändern, wenn genau das ihre Aufgabe ist.":"مقدارهای ابتدایی مثل عددها و متن‌ها به شکل کپی داده می‌شوند. در شیءها و آرایه‌ها تابع یک ارجاع می‌گیرد: اگر شیء را تغییر دهد، تغییر بیرون هم دیده می‌شود. به همین دلیل یک تابع فقط وقتی باید شیءهای داده‌شده را تغییر دهد که دقیقاً کارش همین باشد.","`return` beendet die Funktion sofort; Code danach wird nicht mehr ausgeführt. Ohne `return` liefert jede Funktion `undefined`. Willst du mehrere Werte zurückgeben, nutze ein Objekt oder Array: `return { summe, anzahl };`.":"`return` تابع را فوراً تمام می‌کند؛ کد بعد از آن دیگر اجرا نمی‌شود. بدون `return` هر تابع `undefined` برمی‌گرداند. اگر بخواهید چند مقدار برگردانید، از یک شیء یا آرایه استفاده کنید: `return { summe, anzahl };`.","Funktionen, die nur aus ihren Parametern ein Ergebnis berechnen und sonst nichts verändern, heißen reine Funktionen. Sie sind leicht zu testen, weil derselbe Aufruf immer dasselbe Ergebnis liefert. Ausgaben in die Konsole oder Änderungen an der Seite heißen dagegen Nebenwirkungen.":"تابع‌هایی که فقط از پارامترهایشان یک نتیجه حساب می‌کنند و چیز دیگری را تغییر نمی‌دهند، تابع‌های خالص نام دارند. آزمایششان آسان است، چون همان صدا زدن همیشه همان نتیجه را می‌دهد. اما نمایش در کنسول یا تغییر در صفحه را اثر جانبی می‌نامند.","Ohne Klammern ist `doppelt` die Funktion selbst, mit Klammern `doppelt(4)` ihr Ergebnis. Diesen Unterschied brauchst du bei Ereignissen: `knopf.addEventListener('click', speichern)` übergibt die Funktion, damit sie später aufgerufen wird. `speichern()` würde sie sofort ausführen.":"بدون پرانتز `doppelt` خود تابع است و با پرانتز `doppelt(4)` نتیجهٔ آن. این فرق را در رویدادها لازم دارید: `knopf.addEventListener('click', speichern)` تابع را می‌دهد تا بعداً صدا زده شود. `speichern()` آن را فوراً اجرا می‌کرد.","Funktionen sind in JavaScript Werte erster Klasse: Man kann sie in Variablen speichern, anderen Funktionen übergeben und aus Funktionen zurückgeben. Darauf beruhen `map`, `filter` und `addEventListener`. Diese Idee stammt aus der funktionalen Programmierung.":"تابع‌ها در JavaScript مقدارهای درجهٔ یک هستند: می‌توان آن‌ها را در متغیر ذخیره کرد، به تابع‌های دیگر داد و از تابع‌ها برگرداند. `map`، `filter` و `addEventListener` بر همین استوارند. این ایده از برنامه‌نویسی تابعی آمده است.","Objekte sind Sammlungen von Schlüssel-Wert-Paaren, ähnlich wie Dictionaries in Python. Die Schlüssel sind Texte, die man meist ohne Anführungszeichen schreibt. Werte können alles sein, auch Arrays, andere Objekte oder Funktionen – eine Funktion in einem Objekt heißt Methode.":"شیءها مجموعه‌هایی از جفت‌های کلید-مقدار هستند، شبیه دیکشنری‌ها در پایتون. کلیدها متن هستند که معمولاً بدون نقل‌قول نوشته می‌شوند. مقدارها می‌توانند هر چیزی باشند، حتی آرایه، شیءهای دیگر یا تابع – تابعی داخل یک شیء متد نام دارد.","Die Schreibweise mit geschweiften Klammern heißt Objektliteral. Sie ist auch die Grundlage des Datenformats JSON, mit dem Webseiten und Server Daten austauschen. Gibt es eine Variable mit demselben Namen wie die Eigenschaft, reicht die Kurzform `{ name, ort }`.":"نوشتار با آکولاد را لفظ شیء (Object Literal) می‌نامند. این پایهٔ قالب دادهٔ JSON هم هست که صفحه‌های وب و سرورها با آن داده تبادل می‌کنند. اگر متغیری با همان نام ویژگی باشد، شکل کوتاه `{ name, ort }` کافی است.","Neben der Punktschreibweise gibt es die Klammerschreibweise: `person['name']`. Sie ist nötig, wenn der Name in einer Variable steht (`person[feld]`) oder Sonderzeichen enthält. Mit `const { name, ort } = person;` holst du mehrere Eigenschaften auf einmal heraus; das nennt man Destrukturierung.":"کنار نوشتار نقطه‌ای نوشتار کروشه‌ای هم هست: `person['name']`. وقتی لازم است که نام در یک متغیر باشد (`person[feld]`) یا نویسه‌های خاص داشته باشد. با `const { name, ort } = person;` چند ویژگی را یک‌جا بیرون می‌آورید؛ به این تجزیه (Destructuring) می‌گویند.","`Object.keys(person)` liefert alle Schlüssel als Array, `Object.values(person)` alle Werte und `Object.entries(person)` Paare aus beidem. Damit kannst du mit einer Schleife über alle Eigenschaften eines Objekts laufen.":"`Object.keys(person)` همهٔ کلیدها را به شکل آرایه می‌دهد، `Object.values(person)` همهٔ مقدارها را و `Object.entries(person)` جفت‌هایی از هر دو را. با این‌ها می‌توانید با یک حلقه روی همهٔ ویژگی‌های یک شیء بگردید.","Neue Eigenschaften entstehen einfach durch Zuweisung, etwa `person.alter = 34`. Mit `delete person.alter` entfernst du eine Eigenschaft wieder. Willst du ein Objekt vollständig gegen Änderungen schützen, gibt es `Object.freeze(person)`.":"ویژگی‌های تازه ساده با اختصاص ساخته می‌شوند، مثلاً `person.alter = 34`. با `delete person.alter` یک ویژگی را دوباره حذف می‌کنید. اگر بخواهید یک شیء را کاملاً در برابر تغییر محافظت کنید، `Object.freeze(person)` هست.","Weil Variablen bei Objekten nur Verweise speichern, ist `const kopie = person;` keine Kopie. Eine flache Kopie entsteht mit `{ ...person }`. Enthält das Objekt weitere Objekte, kopiert `structuredClone(person)` auch diese verschachtelten Teile.":"چون متغیرها در شیءها فقط ارجاع ذخیره می‌کنند، `const kopie = person;` کپی نیست. یک کپی سطحی با `{ ...person }` ساخته می‌شود. اگر شیء شیءهای دیگری داشته باشد، `structuredClone(person)` این بخش‌های تودرتو را هم کپی می‌کند.","Eine fehlende Eigenschaft liefert `undefined`. Problematisch wird es eine Ebene tiefer: `person.adresse.ort` erzeugt einen TypeError, wenn `adresse` fehlt. Der Operator `?.` (optionale Verkettung) verhindert das: `person.adresse?.ort` ergibt dann einfach `undefined`.":"یک ویژگی کم `undefined` می‌دهد. مشکل یک سطح پایین‌تر پیش می‌آید: `person.adresse.ort` یک TypeError می‌سازد اگر `adresse` نباشد. عملگر `?.` (زنجیرهٔ اختیاری) جلوی این را می‌گیرد: `person.adresse?.ort` آن وقت ساده `undefined` می‌شود.","Mit `??` gibst du einen Ersatzwert an: `person.ort ?? 'unbekannt'`. Anders als `||` greift `??` nur bei `null` und `undefined`, nicht bei `0` oder einem leeren Text. Ob eine Eigenschaft existiert, prüfst du sauber mit `'ort' in person` oder `Object.hasOwn(person, 'ort')`.":"با `??` یک مقدار جایگزین می‌دهید: `person.ort ?? 'unbekannt'`. برخلاف `||`، `??` فقط در `null` و `undefined` اثر می‌کند، نه در `0` یا یک متن خالی. اینکه یک ویژگی وجود دارد را تمیز با `'ort' in person` یا `Object.hasOwn(person, 'ort')` بررسی می‌کنید.","DOM heißt Document Object Model. Der Browser übersetzt den HTML-Text in einen Baum aus Objekten: Das Dokument ist die Wurzel, darunter liegen `html`, `head` und `body`, und darunter die einzelnen Elemente. Text zwischen den Tags bildet eigene Textknoten.":"DOM یعنی Document Object Model. مرورگر متن HTML را به درختی از شیءها ترجمه می‌کند: سند ریشه است، زیر آن `html`، `head` و `body` و زیر آن‌ها عنصرهای تکی. متن بین برچسب‌ها گره‌های متنی جداگانه می‌سازد.","Ändert JavaScript den DOM-Baum, aktualisiert der Browser die Anzeige automatisch. Der ursprüngliche HTML-Quelltext bleibt dabei unverändert – in den Entwicklerwerkzeugen siehst du unter „Elements“ den aktuellen DOM, unter „Seitenquelltext anzeigen“ das ursprüngliche HTML.":"اگر JavaScript درخت DOM را تغییر دهد، مرورگر نمایش را خودکار به‌روز می‌کند. متن منبع اصلی HTML در این میان تغییر نمی‌کند – در ابزار توسعه‌دهنده زیر «Elements» DOM فعلی و زیر «نمایش متن منبع صفحه» HTML اصلی را می‌بینید.","`querySelector` liefert das erste passende Element, `querySelectorAll` alle als Liste, die du mit `for...of` durchlaufen kannst. Du kannst jeden CSS-Selektor verwenden: `'.hinweis'`, `'nav a'` oder `'[type=email]'`. Daneben gibt es das ältere, schnelle `document.getElementById('ausgabe')`.":"`querySelector` اولین عنصر مناسب را می‌دهد و `querySelectorAll` همه را به شکل لیستی که می‌توانید با `for...of` بگردید. می‌توانید از هر انتخابگر CSS استفاده کنید: `'.hinweis'`، `'nav a'` یا `'[type=email]'`. کنار آن `document.getElementById('ausgabe')` قدیمی‌تر و سریع هست.","Eine Suche im DOM kostet etwas Zeit. Speichere ein Element deshalb in einer Variable, wenn du es mehrmals brauchst, statt es jedes Mal neu zu suchen. In großen Anwendungen bündelt man solche Verweise oft am Anfang eines Skripts.":"یک جستجو در DOM کمی وقت می‌گیرد. پس اگر یک عنصر را چند بار لازم دارید، آن را در یک متغیر ذخیره کنید، به جای اینکه هر بار دوباره بگردید. در برنامه‌های بزرگ چنین ارجاع‌هایی اغلب در اول یک اسکریپت جمع می‌شوند.","`innerHTML` wertet den zugewiesenen Text als HTML aus. Stammt der Text von Nutzern, könnte jemand darin ein Skript einschleusen, das im Browser anderer Besucher ausgeführt wird. Diese Angriffsart heißt Cross-Site-Scripting (XSS) und gehört zu den häufigsten Sicherheitslücken im Web.":"`innerHTML` متن داده‌شده را به عنوان HTML ارزیابی می‌کند. اگر متن از کاربران باشد، کسی ممکن است داخل آن یک اسکریپت بگذارد که در مرورگر بازدیدکنندگان دیگر اجرا شود. این نوع حمله Cross-Site-Scripting (XSS) نام دارد و از رایج‌ترین حفره‌های امنیتی وب است.","`textContent` zeigt alles als reinen Text, auch spitze Klammern. Für neue Elemente nutzt du `document.createElement` und setzt Inhalte mit `textContent`. Klassen änderst du mit `element.classList.add('aktiv')` und `remove`, statt Stile direkt im Skript festzulegen.":"`textContent` همه چیز را به شکل متن ساده نشان می‌دهد، حتی علامت‌های کوچک‌تر و بزرگ‌تر را. برای عنصرهای تازه از `document.createElement` استفاده می‌کنید و محتوا را با `textContent` می‌گذارید. کلاس‌ها را با `element.classList.add('aktiv')` و `remove` تغییر می‌دهید، به جای اینکه سبک‌ها را مستقیم در اسکریپت تعیین کنید.","Ein `script` im `head` läuft, bevor der Browser den `body` gelesen hat – `querySelector` findet dann noch nichts und liefert `null`. Abhilfe: das Skript am Ende des `body` einbinden oder im `head` mit dem Attribut `defer` laden. Mit `defer` wartet der Browser, bis das HTML vollständig gelesen ist.":"یک `script` در `head` پیش از اینکه مرورگر `body` را خوانده باشد اجرا می‌شود – `querySelector` آن وقت هنوز چیزی پیدا نمی‌کند و `null` می‌دهد. راه حل: اسکریپت را در آخر `body` بگذارید یا در `head` با ویژگی `defer` بار کنید. با `defer` مرورگر صبر می‌کند تا HTML کامل خوانده شود.","Eine Prüfung wie `if (ausgabe)` macht Code robust, wenn ein Element auf manchen Seiten fehlt. Die Kurzform `ausgabe?.append(...)` erledigt Prüfung und Aufruf auf einmal. In der Konsole zeigt ein Fehler wie „Cannot set properties of null“ genau dieses Problem an.":"بررسی‌ای مثل `if (ausgabe)` کد را مقاوم می‌کند وقتی یک عنصر در بعضی صفحه‌ها نیست. شکل کوتاه `ausgabe?.append(...)` بررسی و صدا زدن را یک‌جا انجام می‌دهد. در کنسول خطایی مثل «Cannot set properties of null» دقیقاً همین مشکل را نشان می‌دهد.","Der Browser erzeugt laufend Ereignisse: Klicks, Tastendrücke, Eingaben in Felder (`input`), Absenden von Formularen (`submit`), Scrollen und das Laden der Seite. JavaScript im Browser ist ereignisgesteuert: Code läuft meist als Reaktion auf so ein Ereignis.":"مرورگر پیوسته رویداد می‌سازد: کلیک‌ها، فشار کلیدها، ورودی در خانه‌ها (`input`)، فرستادن فرم‌ها (`submit`)، اسکرول و بار شدن صفحه. JavaScript در مرورگر رویدادمحور است: کد بیشتر به عنوان واکنش به چنین رویدادی اجرا می‌شود.","Ereignisse steigen im DOM-Baum nach oben (Bubbling): Ein Klick auf einen Link löst das Ereignis auch an der umgebenden Liste und am Dokument aus. Deshalb kann ein einziger Listener an einer Liste alle Klicks auf ihre Einträge abfangen. Dieses Muster heißt Event-Delegation.":"رویدادها در درخت DOM به بالا می‌روند (Bubbling): یک کلیک روی یک لینک رویداد را در لیست دربرگیرنده و در سند هم ایجاد می‌کند. به همین دلیل یک گوش‌دهندهٔ تنها روی یک لیست می‌تواند همهٔ کلیک‌ها روی عنصرهایش را بگیرد. این الگو را واگذاری رویداد (Event Delegation) می‌نامند.","Die Listener-Funktion bekommt automatisch ein Ereignisobjekt als Parameter, meist `event` oder `e` genannt. `event.target` ist das Element, auf das geklickt wurde, `event.key` die gedrückte Taste. Mit `event.preventDefault()` verhinderst du das Standardverhalten, etwa das Neuladen beim Absenden eines Formulars.":"تابع گوش‌دهنده خودکار یک شیء رویداد به عنوان پارامتر می‌گیرد که معمولاً `event` یا `e` نامیده می‌شود. `event.target` عنصری است که روی آن کلیک شده و `event.key` کلید فشرده‌شده. با `event.preventDefault()` جلوی رفتار پیش‌فرض را می‌گیرید، مثلاً بار شدن دوباره در فرستادن یک فرم.","Ein Element kann mehrere Listener für dasselbe Ereignis haben. Mit `removeEventListener` entfernst du einen wieder – dafür brauchst du dieselbe Funktion, also eine benannte, keine anonyme. Mit der Option `{ once: true }` läuft ein Listener nur ein einziges Mal.":"یک عنصر می‌تواند برای همان رویداد چند گوش‌دهنده داشته باشد. با `removeEventListener` یکی را دوباره حذف می‌کنید – برای آن همان تابع را لازم دارید، یعنی یک تابع نام‌دار، نه بی‌نام. با گزینهٔ `{ once: true }` یک گوش‌دهنده فقط یک بار اجرا می‌شود.","Gute Rückmeldung folgt sofort und sagt klar, was passiert ist. Bei längeren Vorgängen zeigt man zuerst einen Zwischenstand wie „Wird gespeichert …“ und deaktiviert den Knopf, damit niemand doppelt klickt. Fehler werden mit einer verständlichen Erklärung gemeldet.":"بازخورد خوب فوراً می‌آید و روشن می‌گوید چه اتفاقی افتاد. در روندهای طولانی‌تر اول یک وضعیت میانی مثل «در حال ذخیره …» نشان می‌دهند و دکمه را غیرفعال می‌کنند تا کسی دو بار کلیک نکند. خطاها با یک توضیح قابل فهم اعلام می‌شوند.","Für Vorleseprogramme gibt es Live-Bereiche: Ein Element mit `aria-live=\"polite\"` wird vorgelesen, sobald sich sein Text ändert. So erfahren auch blinde Menschen, dass ihre Aktion geklappt hat. Wichtig ist, dass die Meldung als Text erscheint und nicht nur als Farbwechsel.":"برای برنامه‌های بلندخوان بخش‌های زنده هستند: عنصری با `aria-live=\"polite\"` همین که متنش تغییر کند خوانده می‌شود. به این ترتیب نابینایان هم می‌فهمند که کارشان موفق بوده است. مهم این است که پیام به شکل متن بیاید و نه فقط به شکل تغییر رنگ.","Ein `button` löst das `click`-Ereignis auch bei Enter und Leertaste aus. Hängst du dagegen einen Klick-Listener an ein `div`, erreichen Tastaturnutzer es nicht einmal mit Tab. Man müsste `tabindex`, eine Rolle und eigene Tastenbehandlung ergänzen – fehleranfällig und unnötig.":"یک `button` رویداد `click` را با Enter و Space هم ایجاد می‌کند. اما اگر یک گوش‌دهندهٔ کلیک به یک `div` وصل کنید، کاربران کیبورد حتی با Tab هم به آن نمی‌رسند. باید `tabindex`، یک نقش و رسیدگی جداگانه به کلیدها اضافه شود – پرخطا و غیرلازم.","Teste jede interaktive Seite ohne Maus: Mit Tab vorwärts, mit Umschalt+Tab zurück, mit Enter oder Leertaste auslösen. Ein sichtbarer Fokusrahmen muss dabei immer zeigen, wo man gerade ist. Entferne ihn nie ersatzlos mit `outline: none`.":"هر صفحهٔ تعاملی را بدون ماوس آزمایش کنید: با Tab به جلو، با Shift+Tab به عقب، با Enter یا Space فعال کردن. یک قاب فوکوس دیدنی باید همیشه نشان دهد کجا هستید. هرگز آن را بدون جایگزین با `outline: none` حذف نکنید.","Neben `console.log` gibt es `console.warn` und `console.error`, die farblich hervorgehoben werden, sowie `console.table` für Arrays und Objekte als übersichtliche Tabelle. Mit Filtern in der Konsole kannst du gezielt nur Fehler oder nur bestimmte Texte anzeigen.":"کنار `console.log`، `console.warn` و `console.error` هستند که با رنگ برجسته می‌شوند، و `console.table` برای آرایه‌ها و شیءها به شکل یک جدول مرتب. با فیلترها در کنسول می‌توانید هدفمند فقط خطاها یا فقط متن‌های مشخص را نشان دهید.","Gibst du ein Objekt mit `console.log` aus, zeigt manche Konsole beim Aufklappen den aktuellen Zustand, nicht den Zustand zum Zeitpunkt der Ausgabe. Willst du einen Zwischenstand festhalten, gib eine Kopie aus, etwa `console.log(JSON.stringify(daten))`.":"اگر یک شیء را با `console.log` نمایش دهید، بعضی کنسول‌ها در وقت باز کردن وضعیت فعلی را نشان می‌دهند، نه وضعیت لحظهٔ نمایش را. اگر بخواهید یک وضعیت میانی را نگه دارید، یک کپی نمایش دهید، مثلاً `console.log(JSON.stringify(daten))`.","Ein SyntaxError entsteht schon beim Einlesen des Skripts. Deshalb läuft dann das ganze Skript nicht, nicht nur die fehlerhafte Zeile. Die Konsole nennt Datei und Zeilennummer; ein Klick darauf öffnet die Stelle im Quelltext.":"یک SyntaxError از همان وقت خوانده شدن اسکریپت پیش می‌آید. به همین دلیل آن وقت کل اسکریپت اجرا نمی‌شود، نه فقط خط نادرست. کنسول فایل و شمارهٔ خط را نام می‌برد؛ کلیک روی آن جای مربوط را در متن منبع باز می‌کند.","Typische Ursachen sind vergessene Klammern, fehlende Anführungszeichen und Tippfehler in Schlüsselwörtern. Editoren mit Syntaxhervorhebung zeigen solche Fehler oft schon beim Schreiben durch Farben oder Wellenlinien. Ein Formatierer wie Prettier macht falsch geschlossene Klammern zusätzlich sichtbar.":"علت‌های معمول پرانتزهای فراموش‌شده، نقل‌قول‌های کم و اشتباه تایپی در کلیدواژه‌ها هستند. ویرایشگرهایی با رنگ‌آمیزی نوشتار اغلب چنین خطاهایی را از همان وقت نوشتن با رنگ یا خط موجی نشان می‌دهند. یک قالب‌بندی‌کننده مثل Prettier پرانتزهای نادرست بسته‌شده را علاوه بر آن دیدنی می‌کند.","Ein TypeError tritt erst zur Laufzeit auf, wenn ein Wert nicht den erwarteten Typ hat, etwa wenn du auf eine Eigenschaft von `null` zugreifst oder etwas aufrufst, das keine Funktion ist. Die Meldung „Cannot read properties of null (reading 'textContent')“ sagt genau, welcher Zugriff scheiterte.":"یک TypeError تازه در وقت اجرا پیش می‌آید، وقتی یک مقدار نوع مورد انتظار را ندارد، مثلاً وقتی به ویژگی‌ای از `null` دسترسی می‌خواهید یا چیزی را صدا می‌زنید که تابع نیست. پیام «Cannot read properties of null (reading 'textContent')» دقیقاً می‌گوید کدام دسترسی شکست خورد.","Ein ReferenceError bedeutet dagegen, dass ein Name gar nicht existiert, meist wegen eines Tippfehlers. Lies die Meldung vollständig: Sie enthält Fehlertyp, Beschreibung und einen Stack-Trace mit der Kette der Funktionsaufrufe bis zur Fehlerstelle.":"اما یک ReferenceError یعنی یک نام اصلاً وجود ندارد، بیشتر به خاطر اشتباه تایپی. پیام را کامل بخوانید: نوع خطا، توضیح و یک Stack-Trace با زنجیرهٔ صدا زدن تابع‌ها تا جای خطا دارد.","Die Entwicklerwerkzeuge enthalten einen Debugger: Mit einem Haltepunkt (Breakpoint) – ein Klick auf die Zeilennummer im Tab „Sources“ – hält das Skript an dieser Stelle an. Dann kannst du alle Variablen ansehen und Zeile für Zeile weitergehen. Im Code bewirkt die Anweisung `debugger;` dasselbe.":"ابزار توسعه‌دهنده یک اشکال‌زدا (Debugger) دارد: با یک نقطهٔ توقف (Breakpoint) – کلیک روی شمارهٔ خط در زبانهٔ «Sources» – اسکریپت در آن جا می‌ایستد. آن وقت می‌توانید همهٔ متغیرها را ببینید و خط به خط جلو بروید. در کد دستور `debugger;` همین کار را می‌کند.","Eine bewährte Methode ist das Gummienten-Debugging: Erkläre jemandem – oder einer Gummiente – Zeile für Zeile, was dein Code tun soll. Beim lauten Erklären fällt der Fehler oft selbst auf. Dahinter steckt dasselbe Prinzip wie beim schrittweisen Testen: Annahmen gezielt überprüfen.":"یک روش آزموده اشکال‌زدایی اردک پلاستیکی است: برای کسی – یا یک اردک پلاستیکی – خط به خط توضیح دهید که کدتان باید چه کند. در وقت توضیح بلند، خطا اغلب خودش پیدا می‌شود. پشت این همان اصل آزمایش قدم به قدم است: بررسی هدفمند فرض‌ها.","Pack Feld und Knopf in ein `form`-Element und reagiere auf das Ereignis `submit`. Dann funktioniert das Hinzufügen per Klick und per Enter-Taste gleichermaßen. Vergiss im Listener `event.preventDefault()`, sonst lädt der Browser die Seite neu und die Liste ist leer.":"خانه و دکمه را داخل یک عنصر `form` بگذارید و به رویداد `submit` واکنش نشان دهید. آن وقت اضافه کردن با کلیک و با کلید Enter به یک اندازه کار می‌کند. `event.preventDefault()` را در گوش‌دهنده فراموش نکنید، وگرنه مرورگر صفحه را دوباره بار می‌کند و لیست خالی می‌شود.","Die Aufgabenliste selbst ist am besten ein `ul`-Element. Vorleseprogramme sagen dann an, wie viele Einträge die Liste hat. Ein Attribut wie `maxlength` begrenzt die Länge der Eingabe und schützt so das Layout vor extrem langen Texten.":"خود لیست کارها بهتر است یک عنصر `ul` باشد. آن وقت برنامه‌های بلندخوان اعلام می‌کنند لیست چند عنصر دارد. ویژگی‌ای مثل `maxlength` طول ورودی را محدود می‌کند و به این ترتیب چیدمان را در برابر متن‌های بسیار طولانی محافظت می‌کند.","`value` liefert immer einen String, auch bei Zahlenfeldern. `trim()` entfernt Leerzeichen, Tabs und Zeilenumbrüche an beiden Enden, nicht in der Mitte. Ein leerer String ist „falsy“, deshalb reicht die Prüfung `if (!text) return;`.":"`value` همیشه یک رشته می‌دهد، حتی در خانه‌های عددی. `trim()` فاصله‌ها، تب‌ها و رفتن به خط بعد را در هر دو سر حذف می‌کند، نه در وسط. یک رشتهٔ خالی «falsy» است، به همین دلیل بررسی `if (!text) return;` کافی است.","Gib eine kurze Rückmeldung, wenn eine leere Eingabe abgelehnt wird, und setze den Fokus mit `feld.focus()` zurück ins Feld. So weiß die Person sofort, was zu tun ist. Prüfe auch auf doppelte Einträge, falls das für deine Liste sinnvoll ist.":"وقتی یک ورودی خالی رد می‌شود، یک بازخورد کوتاه بدهید و فوکوس را با `feld.focus()` به خانه برگردانید. به این ترتیب شخص فوراً می‌داند چه باید بکند. اگر برای لیستتان معقول است، ورودی‌های تکراری را هم بررسی کنید.","Neue Elemente zuerst vollständig vorzubereiten und dann einzufügen ist effizient, weil der Browser die Anzeige nur einmal neu berechnen muss. Statt `appendChild` kannst du auch das modernere `append` verwenden, das mehrere Elemente und sogar Texte auf einmal annimmt.":"اول کامل آماده کردن عنصرهای تازه و بعد اضافه کردن آن‌ها کارآمد است، چون مرورگر باید نمایش را فقط یک بار دوباره حساب کند. به جای `appendChild` می‌توانید `append` امروزی‌تر را هم به کار ببرید که چند عنصر و حتی متن را یک‌جا می‌پذیرد.","Um Aufgaben abhaken oder löschen zu können, bekommt jeder Eintrag einen eigenen Knopf. Mit Event-Delegation reicht ein einziger Listener an der Liste, der über `event.target` erkennt, welcher Knopf gedrückt wurde. So funktionieren auch Einträge, die erst später hinzukommen.":"برای اینکه بتوان کارها را تیک زد یا حذف کرد، هر عنصر یک دکمهٔ جداگانه می‌گیرد. با واگذاری رویداد یک گوش‌دهندهٔ تنها روی لیست کافی است که از راه `event.target` می‌فهمد کدام دکمه فشرده شد. به این ترتیب عنصرهایی که بعداً اضافه می‌شوند هم کار می‌کنند.","Damit die Liste ein Neuladen übersteht, speicherst du sie mit `localStorage.setItem('aufgaben', JSON.stringify(liste))` und liest sie beim Start mit `JSON.parse` wieder ein. Die Daten bleiben dann nur in diesem Browser auf diesem Gerät gespeichert und werden nicht übertragen.":"برای اینکه لیست از بار شدن دوباره جان سالم به در ببرد، آن را با `localStorage.setItem('aufgaben', JSON.stringify(liste))` ذخیره می‌کنید و در شروع با `JSON.parse` دوباره می‌خوانید. داده‌ها آن وقت فقط در همین مرورگر روی همین دستگاه ذخیره می‌مانند و منتقل نمی‌شوند.","Eine saubere Struktur trennt Daten und Anzeige: Ein Array hält die Aufgaben, und eine Funktion `zeichnen()` baut die Liste aus diesem Array neu auf. Jede Änderung verändert zuerst das Array und ruft dann `zeichnen()` auf. Dieses Prinzip ist die Grundidee moderner Frameworks wie React und Vue.":"یک ساختار تمیز داده و نمایش را جدا می‌کند: یک آرایه کارها را نگه می‌دارد و یک تابع `zeichnen()` لیست را از این آرایه دوباره می‌سازد. هر تغییر اول آرایه را تغییر می‌دهد و بعد `zeichnen()` را صدا می‌زند. این اصل ایدهٔ پایه‌ای چارچوب‌های امروزی مثل React و Vue است.","Eine Zahl wie 12 lässt sich direkt berechnen. Ohne Anführungszeichen speichert JavaScript einen numerischen Wert. Für einen festen Preis ist const geeignet. Ein Preisetikett trägt eine Zahl, nicht den geschriebenen Namen der Zahl. Zeile 1 legt preis mit `const` fest; Zeile 2 legt ort als Zeichenkette an. Vergleiche `12 + 3` mit `'12' + 3` und beobachte `15` gegenüber `123`.":"عددی مثل 12 را می‌شود مستقیم حساب کرد. بدون علامهٔ نقل‌قول، JavaScript یک مقدار عددی نگه می‌دارد. برای یک قیمت ثابت const مناسب است. یک برچسب قیمت یک عدد دارد، نه نام نوشته‌شدهٔ آن عدد را. خط 1 ‏preis را با `const` تعیین می‌کند؛ خط 2 ‏ort را به شکل رشتهٔ متنی می‌سازد. `12 + 3` را با `'12' + 3` مقایسه کنید و `15` را در برابر `123` ببینید.","Ein Boolean ist entweder true oder false. Er steht ohne Anführungszeichen im Code. So kannst du Zustände wie offen oder geschlossen speichern. Ein Lichtschalter hat zwei Zustände; Boolean bildet genau diese Unterscheidung ab. `const offen = true;` legt einen echten Wahrheitswert an. `if (offen)` kann damit eine Entscheidung treffen, ohne Text zu vergleichen.":"یک Boolean یا true است یا false. بدون علامهٔ نقل‌قول در کد نوشته می‌شود. به این ترتیب می‌توانید وضعیت‌هایی مثل باز یا بسته را نگه دارید. یک سویچ چراغ دو وضعیت دارد؛ Boolean دقیقاً همین تفاوت را نشان می‌دهد. `const offen = true;` یک مقدار درست/نادرست واقعی می‌سازد. `if (offen)` با آن می‌تواند تصمیم بگیرد، بدون اینکه متن را مقایسه کند.","Ein Array sammelt mehrere Werte in eckigen Klammern. Trenne die Einträge mit Kommas. So bleibt eine Einkaufsliste in einer einzigen Variablen. Eine Einkaufstasche enthält mehrere Produkte; ein Array hält ihre Namen zusammen. `const einkauf = ['Brot', 'Milch'];` erzeugt zwei Einträge. Die eckigen Klammern gehören zur Liste, die Anführungszeichen zu jedem Text.":"یک آرایه چند مقدار را داخل قوس‌های چهارگوش جمع می‌کند. عنصرها را با کامه جدا کنید. به این ترتیب یک لست خرید در یک متغیر واحد می‌ماند. یک خریطهٔ خرید چند جنس دارد؛ یک آرایه نام‌های آن‌ها را یک‌جا نگه می‌دارد. `const einkauf = ['Brot', 'Milch'];` دو عنصر می‌سازد. قوس‌های چهارگوش به لست تعلق دارند و علامهٔ نقل‌قول به هر متن.","Eine Schleife führt denselben Ablauf mehrmals aus. Du musst die Anweisung nicht kopieren. Das ist bei einer Liste von Namen besonders praktisch. Eine Lehrkraft ruft alle Namen der Anwesenheitsliste nacheinander auf. `for (const name of namen)` besucht jeden vorhandenen Eintrag. Der Block in geschweiften Klammern wird für jeden Namen wiederholt.":"یک حلقه یک روند را چند بار اجرا می‌کند. لازم نیست دستور را کاپی کنید. این برای یک لست نام‌ها به‌خصوص کاربردی است. یک معلم همهٔ نام‌های لست حاضری را یکی پس از دیگری صدا می‌زند. `for (const name of namen)` به هر عنصر موجود سر می‌زند. بلاک داخل قوس‌های گُل‌دار برای هر نام تکرار می‌شود.","Eine klassische for-Schleife benutzt oft let i = 0. Nach jedem Durchlauf erhöht i++ den Zähler. Mit i < 3 läuft der Block genau dreimal. Eine Nummernausgabe am Schalter zählt 0, 1, 2 und stoppt dann. `let i = 0` setzt den Anfangswert, `i < 3` prüft die Grenze. `i++` erhöht die Nummer nach jedem Durchlauf um eins.":"یک حلقهٔ for کلاسیک اغلب let i = 0 را به کار می‌برد. بعد از هر دور i++ شمارنده را زیاد می‌کند. با i < 3 بلاک دقیقاً سه بار اجرا می‌شود. یک دستگاه نوبت در کاونتر 0، 1، 2 می‌شمارد و بعد می‌ایستد. `let i = 0` مقدار شروع را می‌گذارد و `i < 3` حد را بررسی می‌کند. `i++` بعد از هر دور شماره را یکی زیاد می‌کند.","Eine Schleife braucht eine erreichbare Abbruchbedingung. Ohne Änderung des Zählers kann sie endlos laufen. Prüfe den Ablauf zunächst mit wenigen Werten. Eine Rolltreppe ohne Ausgang wäre gefährlich; eine Schleife ohne Ende blockiert den Ablauf. Bei `for (let i = 0; i < 3; i++)` ist das Ende erreichbar. Wenn `i++` fehlt, bleibt die Bedingung dauerhaft wahr.":"یک حلقه به یک شرط توقف قابل رسیدن نیاز دارد. بدون تغییر شمارنده ممکن است بی‌پایان اجرا شود. روند را اول با چند مقدار کم بررسی کنید. یک زینهٔ برقی بدون خروجی خطرناک می‌بود؛ یک حلقهٔ بی‌پایان روند را متوقف می‌کند. در `for (let i = 0; i < 3; i++)` پایان قابل رسیدن است. اگر `i++` نباشد، شرط همیشه درست می‌ماند.","Eine Funktion bündelt einen wiederkehrenden Ablauf. function leitet die Definition ein. Der Name beschreibt die Aufgabe möglichst genau. Eine Kaffeemaschine erledigt nach dem Start immer dieselben Schritte. `function doppelt(zahl)` gibt dem Ablauf einen Namen und einen Parameter. Die geschweiften Klammern umschließen die Rechenanweisung.":"یک تابع یک روند تکراری را یک‌جا جمع می‌کند. function تعریف را شروع می‌کند. نام باید کار را تا حد ممکن دقیق توصیف کند. یک ماشین قهوه بعد از روشن شدن همیشه همان قدم‌ها را انجام می‌دهد. `function doppelt(zahl)` به روند یک نام و یک پارامتر می‌دهد. قوس‌های گُل‌دار دستور حساب را در بر می‌گیرند.","In runden Klammern stehen Parameter. Beim Aufruf wird für jeden Parameter ein Wert übergeben. Im Funktionskörper kannst du damit rechnen. Eine Bestellung nennt die gewünschte Menge; ein Parameter übernimmt diesen Wert. `doppelt(4)` übergibt die Zahl vier an den Parameter zahl. Im Funktionskörper steht dann für zahl genau dieser Wert.":"داخل قوس‌های گرد پارامترها هستند. هنگام صدا زدن برای هر پارامتر یک مقدار داده می‌شود. در بدنهٔ تابع می‌توانید با آن حساب کنید. یک سفارش مقدار دلخواه را نام می‌برد؛ یک پارامتر این مقدار را می‌گیرد. `doppelt(4)` عدد چهار را به پارامتر zahl می‌دهد. در بدنهٔ تابع به جای zahl دقیقاً همین مقدار قرار می‌گیرد.","Ein Objekt speichert zusammengehörige Angaben. Zwischen geschweiften Klammern stehen Eigenschaft und Wert. Ein Doppelpunkt trennt beide Teile. Eine Kontaktkarte hält Name und Ort einer Person beisammen. `const person = { name: 'Amina', ort: 'Bonn' };` erstellt zwei Eigenschaften. Der Doppelpunkt verbindet jeweils Schlüssel und Wert.":"یک آبجکت معلومات مربوط به هم را نگه می‌دارد. بین قوس‌های گُل‌دار ویژگی و مقدار می‌آیند. یک دونقطه هر دو بخش را جدا می‌کند. یک کارت تماس نام و شهر یک شخص را کنار هم نگه می‌دارد. `const person = { name: 'Amina', ort: 'Bonn' };` دو ویژگی می‌سازد. دونقطه هر بار کلید و مقدار را به هم وصل می‌کند.","Prüfe das Element vor dem Zugriff. Eine einfache if-Abfrage verhindert Fehler bei null. Platziere das Skript so, dass das HTML bereits geladen wurde. Ein Briefkasten muss montiert sein, bevor du einen Brief einwerfen kannst. `if (ausgabe)` prüft, ob das Element gefunden wurde. Erst im erfolgreichen Zweig änderst du textContent.":"پیش از دسترسی، عنصر را بررسی کنید. یک if ساده از خطا در null جلوگیری می‌کند. اسکریپت را طوری بگذارید که HTML از قبل بارگیری شده باشد. یک صندوق پست باید نصب شده باشد، پیش از اینکه بتوانید نامه‌ای در آن بیندازید. `if (ausgabe)` بررسی می‌کند که آیا عنصر پیدا شد. فقط در شاخهٔ موفق textContent را تغییر می‌دهید.","Ein echtes button-Element funktioniert auch mit der Tastatur. Teste Tab und Enter. Ein klickbarer Absatz ist dafür keine gleichwertige Lösung. Eine barrierefreie Tür lässt sich auf mehreren Wegen öffnen. Ein HTML-button reagiert neben der Maus auch auf Tastatureingaben. Erreiche den Knopf mit Tab und aktiviere ihn mit Enter.":"یک عنصر button واقعی با کیبورد هم کار می‌کند. Tab و Enter را آزمایش کنید. یک پاراگراف قابل کلیک برای این کار راه‌حل برابر نیست. یک دروازهٔ دسترس‌پذیر از چند راه باز می‌شود. یک button در HTML علاوه بر موس به ورودی‌های کیبورد هم واکنش نشان می‌دهد. با Tab به دکمه برسید و با Enter آن را فعال کنید.","Eine Aufgabenliste braucht ein Eingabefeld. Verbinde label und input über for und id. Der Knopf startet das Hinzufügen. Ein Notizblock braucht eine Zeile für jede neue Aufgabe. `<label for='aufgabe'>` beschreibt das Eingabefeld. Das zugehörige input hat die ID aufgabe.":"یک لست کارها به یک خانهٔ ورودی نیاز دارد. label و input را از راه for و id وصل کنید. دکمه اضافه کردن را شروع می‌کند. یک کتابچهٔ یادداشت برای هر کار تازه یک خط لازم دارد. `<label for='aufgabe'>` خانهٔ ورودی را توصیف می‌کند. input مربوط ID ‏aufgabe را دارد."};})(typeof window!=="undefined"?window:globalThis);
